package com.fogofwar;
import com.fogofwar.config.FadingPlayerMode;
import com.fogofwar.config.FogDisplayMode;
import com.fogofwar.config.FogOfWarConfig;
import com.fogofwar.debug.DebugOverlay;
import com.fogofwar.fade.FadingPlayerManager;
import com.fogofwar.fade.FadingPlayerMinimapOverlay;
import com.fogofwar.fade.FadingPlayerOverlay;
import com.fogofwar.lifecycle.LifecycleComponent;
import com.fogofwar.area.AreaExclusionManager;
import com.fogofwar.render.RenderCenterProvider;
import com.fogofwar.render.minimap.MinimapFogOverlay;
import com.fogofwar.render.world.WorldFogOverlay;
import com.fogofwar.render.world.VisibleActorTracker;
import com.fogofwar.state.ClientState;
import com.google.inject.Provides;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayManager;
import javax.inject.Inject;
import java.awt.Color;
import java.util.List;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Predicate;
@PluginDescriptor(
		name = "Fog of War",
		description = "Applies a fog of war effect outside of the player render distance, in both the world and on the minimap.",
		configName = "FogOfWarPlugin"
)
public class FogOfWarPlugin extends Plugin {
	private static final String CONFIG_GROUP = FogOfWarConfig.CONFIG_GROUP;
	@Inject
	private FogOfWarConfig config;
	@Inject
	private ClientThread clientThread;
	@Inject
	private ClientState clientState;
	@Inject
	private OverlayManager overlayManager;
	@Inject
	private WorldFogOverlay worldOverlay;
	@Inject
	private MinimapFogOverlay minimapOverlay;
	@Inject
	private FadingPlayerManager fadingPlayerManager;
	@Inject
	private FadingPlayerOverlay fadingPlayerOverlay;
	@Inject
	private FadingPlayerMinimapOverlay fadingPlayerMinimapOverlay;
	@Inject
	private AreaExclusionManager areaExclusionManager;
	@Inject
	private RenderCenterProvider renderCenterProvider;
	@Inject
	private VisibleActorTracker visibleActorTracker;
	@Inject
	private DebugOverlay debugOverlay;
	private List<ToggleSpec> overlayToggles = List.of();
	private List<LifecycleSpec> lifecycleComponents = List.of();
	private final AtomicBoolean componentUpdatePending = new AtomicBoolean();
	private volatile boolean started;
	private boolean sailingUpdatesActive;
	private boolean wildernessUpdatesActive;
	@Override
	protected void startUp() {
		started = true;
		updateComponentsOnClientThread();
	}
	@Override
	protected void shutDown() {
		started = false;
		updateComponentsOnClientThread();
	}
	private void initComponents() {
		areaExclusionManager.setOnTransition(this::updateComponents);
		overlayToggles = List.of(
				new ToggleSpec(worldOverlay, state -> state.worldActive, worldOverlay::clearCaches),
				new ToggleSpec(minimapOverlay, state -> state.minimapActive, minimapOverlay::clearCaches),
				new ToggleSpec(debugOverlay, state -> state.debugActive, debugOverlay::clearCaches),
				new ToggleSpec(fadingPlayerOverlay, state -> state.fadingWorldActive),
				new ToggleSpec(fadingPlayerMinimapOverlay, state -> state.fadingMinimapActive, fadingPlayerMinimapOverlay::clearCaches));
		lifecycleComponents = List.of(
				new LifecycleSpec(renderCenterProvider, state -> state.overlayActive || state.debugActive),
				new LifecycleSpec(fadingPlayerManager, state -> state.fadingActive),
				new LifecycleSpec(visibleActorTracker, state -> state.visibleActorTrackingActive));
	}
	@Subscribe
	@SuppressWarnings("unused")
	public void onConfigChanged(ConfigChanged event) {
		if (!CONFIG_GROUP.equals(event.getGroup())) return;
		updateComponentsOnClientThread();
	}
	@Subscribe
	@SuppressWarnings("unused")
	public void onGameStateChanged(GameStateChanged event) {
		if (event.getGameState() == GameState.LOGGED_IN) updateComponents();
		else updateComponents(false);
	}
	@Subscribe
	@SuppressWarnings("unused")
	public void onVarbitChanged(VarbitChanged event) {
		int id = event.getVarbitId();
		if (id == VarbitID.CUTSCENE_STATUS) {
			if (config.disableDuringCutscenes()) updateComponents();
			return;
		}
		if (id == VarbitID.SAILING_BOARDED_BOAT) {
			if (sailingUpdatesActive) updateComponents(event.getValue() == 1);
			return;
		}
		if (wildernessUpdatesActive && id == VarbitID.INSIDE_WILDERNESS) updateComponents();
	}
	private void updateComponents() {
		updateComponents(clientState.isLoggedIn() && (config.disableWhileSailing() || config.showLandAreaWhileSailing()) && clientState.isSailing());
	}
	private void updateComponents(boolean sailing) {
		if (overlayToggles.isEmpty()) initComponents();
		sailingUpdatesActive = config.disableWhileSailing() || config.showLandAreaWhileSailing();
		wildernessUpdatesActive = config.onlyInWilderness();
		ComponentState state = createComponentState(sailing);
		if (state.areaExclusionActive) {
			boolean excluded = areaExclusionManager.isPlayerInExcludedArea();
			areaExclusionManager.start();
			if (excluded != areaExclusionManager.isPlayerInExcludedArea()) state = createComponentState(sailing);
		} else areaExclusionManager.stop();
		for (ToggleSpec overlayToggle : overlayToggles) overlayToggle.update(state);
		for (LifecycleSpec component : lifecycleComponents) component.update(state);
		if (!state.visibleActorTrackingActive) worldOverlay.clearActorCaches();
	}
	private void updateComponentsOnClientThread() {
		if (!componentUpdatePending.compareAndSet(false, true)) return;
		clientThread.invokeLater(() -> {
			componentUpdatePending.set(false);
			updateComponents();
		});
	}
	private ComponentState createComponentState(boolean sailing) {
		if (!started || !clientState.isLoggedIn() || clientState.isCutsceneSuppressed()) return ComponentState.INACTIVE;
		FogDisplayMode worldMode = config.worldDisplayMode();
		FogDisplayMode minimapMode = config.minimapDisplayMode();
		FadingPlayerMode fadingPlayerMode = config.playerFadeMarkerMode();
		boolean showLandAreaWhileSailing = sailing && (worldMode.isEnabled() || minimapMode.isEnabled()) && config.showLandAreaWhileSailing();
		Color worldFogColour = worldMode.showsFog() ? config.worldFogColour() : null;
		Color worldBorderColour = worldMode.showsBorder() ? config.worldBorderColour() : null;
		Color minimapFogColour = minimapMode.showsFog() ? config.minimapFogColour() : null;
		Color minimapBorderColour = minimapMode.showsBorder() ? config.minimapBorderColour() : null;
		boolean worldConfigured = hasVisibleFogOrBorder(worldMode, worldFogColour, worldBorderColour, showLandAreaWhileSailing);
		boolean minimapConfigured = hasVisibleFogOrBorder(minimapMode, minimapFogColour, minimapBorderColour, showLandAreaWhileSailing);
		boolean fadingWorldMode = fadingPlayerMode.showsWorld();
		boolean fadingMinimapMode = fadingPlayerMode.showsMinimap();
		Color fadeColour = fadingWorldMode || fadingMinimapMode ? config.fadeMarkerColour() : null;
		boolean fadingWorldConfigured = fadingWorldMode && hasVisibleFadingWorld(fadingPlayerMode, fadeColour, config.showFadeMarkerNames());
		boolean fadingMinimapConfigured = fadingMinimapMode && hasVisibleFadingMinimap(fadingPlayerMode, fadeColour);
		boolean anyConfigured = worldConfigured || minimapConfigured || fadingWorldConfigured || fadingMinimapConfigured;
		boolean debugConfigured = config.debugOverlayEnabled();
		if (!anyConfigured && !debugConfigured) return ComponentState.INACTIVE;
		boolean globallyEnabled = isGloballyEnabled(sailing);
		boolean areaEnabled = globallyEnabled && (!anyConfigured || !areaExclusionManager.isPlayerInExcludedArea());
		boolean worldActive = areaEnabled && worldConfigured;
		boolean minimapActive = areaEnabled && minimapConfigured;
		boolean fadingWorldActive = areaEnabled && fadingWorldConfigured;
		boolean fadingMinimapActive = areaEnabled && fadingMinimapConfigured;
		boolean fadingActive = fadingWorldActive || fadingMinimapActive;
		boolean overlayActive = worldActive || minimapActive || fadingActive;
		boolean visibleActorTrackingActive = worldActive && worldMode.showsFog() && (worldFogColour.getAlpha() > 0 || showLandAreaWhileSailing) && config.actorCutoutLimit().isEnabled();
		boolean debugActive = areaEnabled && debugConfigured;
		return new ComponentState(worldActive, minimapActive, debugActive, fadingWorldActive, fadingMinimapActive, fadingActive, overlayActive, visibleActorTrackingActive, globallyEnabled && anyConfigured);
	}
	static boolean hasVisibleFogOrBorder(FogDisplayMode mode, Color fog, Color border, boolean showLandAreaWhileSailing) {
		return mode.showsFog() && (fog.getAlpha() > 0 || showLandAreaWhileSailing) || mode.showsBorder() && (border.getAlpha() > 0 || showLandAreaWhileSailing);
	}
	static boolean hasVisibleFadingWorld(FadingPlayerMode mode, Color colour, boolean showNames) { return mode.showsWorld() && (colour.getAlpha() > 0 || showNames); }
	static boolean hasVisibleFadingMinimap(FadingPlayerMode mode, Color colour) { return mode.showsMinimap() && colour.getAlpha() > 0; }
	private boolean isGloballyEnabled(boolean sailing) {
		if (config.onlyInWilderness() && clientState.isNotInWilderness()) return false;
		return !config.disableWhileSailing() || !sailing;
	}
	private final class ToggleSpec {
		private final Overlay overlay;
		private final Predicate<ComponentState> activeFn;
		private final Runnable onDisable;
		private boolean enabled;
		private ToggleSpec(Overlay overlay, Predicate<ComponentState> activeFn) { this(overlay, activeFn, null); }
		private ToggleSpec(Overlay overlay, Predicate<ComponentState> activeFn, Runnable onDisable) {
			this.overlay = overlay;
			this.activeFn = activeFn;
			this.onDisable = onDisable;
		}
		private void update(ComponentState state) {
			boolean enabled = activeFn.test(state);
			if (this.enabled == enabled) return;
			if (enabled) overlayManager.add(overlay);
			else {
				overlayManager.remove(overlay);
				if (onDisable != null) onDisable.run();
			}
			this.enabled = enabled;
		}
	}
	private static final class LifecycleSpec {
		private final LifecycleComponent component;
		private final Predicate<ComponentState> activeFn;
		private LifecycleSpec(LifecycleComponent component, Predicate<ComponentState> activeFn) {
			this.component = component;
			this.activeFn = activeFn;
		}
		private void update(ComponentState state) {
			if (activeFn.test(state)) component.start();
			else component.stop();
		}
	}
	private static final class ComponentState {
		private static final ComponentState INACTIVE = new ComponentState(false, false, false, false, false, false, false, false, false);
		private final boolean worldActive;
		private final boolean minimapActive;
		private final boolean debugActive;
		private final boolean fadingWorldActive;
		private final boolean fadingMinimapActive;
		private final boolean fadingActive;
		private final boolean overlayActive;
		private final boolean visibleActorTrackingActive;
		private final boolean areaExclusionActive;
		private ComponentState(boolean worldActive, boolean minimapActive, boolean debugActive, boolean fadingWorldActive, boolean fadingMinimapActive, boolean fadingActive, boolean overlayActive, boolean visibleActorTrackingActive, boolean areaExclusionActive) {
			this.worldActive = worldActive;
			this.minimapActive = minimapActive;
			this.debugActive = debugActive;
			this.fadingWorldActive = fadingWorldActive;
			this.fadingMinimapActive = fadingMinimapActive;
			this.fadingActive = fadingActive;
			this.overlayActive = overlayActive;
			this.visibleActorTrackingActive = visibleActorTrackingActive;
			this.areaExclusionActive = areaExclusionActive;
		}
	}
	@Provides
	@SuppressWarnings("unused")
	FogOfWarConfig provideConfig(ConfigManager configManager) {
		return configManager.getConfig(FogOfWarConfig.class);
	}
}

package com.fogofwar.area;
import com.fogofwar.lifecycle.LifecycleComponent;
import lombok.Getter;
import lombok.Setter;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameTick;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import javax.inject.Inject;
import javax.inject.Singleton;
@Singleton
public class AreaExclusionManager extends LifecycleComponent {
	private final Client client;
	@Getter
	private boolean playerInExcludedArea = false;
	@Setter
	private Runnable onTransition;
	@Inject
	public AreaExclusionManager(Client client, EventBus eventBus) {
		super(eventBus);
		this.client = client;
	}
	@Override
	protected void onStart() {
		if (client.getGameState() == GameState.LOGGED_IN) playerInExcludedArea = isPlayerInExcludedAreaNow();
	}
	@Override
	protected void onStop() { playerInExcludedArea = false; }
	@Subscribe
	@SuppressWarnings("unused")
	public void onGameTick(GameTick event) { checkArea(); }
	private void checkArea() {
		setPlayerInExcludedArea(isPlayerInExcludedAreaNow());
	}
	private boolean isPlayerInExcludedAreaNow() {
		WorldPoint playerPoint = currentPlayerWorldPoint();
		return playerPoint != null && isExcludedArea(playerPoint);
	}
	private boolean isExcludedArea(WorldPoint playerPoint) {
		for (ExcludedArea area : ExcludedAreas.VALUES) { if (area.contains(playerPoint)) return true; }
		return false;
	}
	private void setPlayerInExcludedArea(boolean value) {
		if (playerInExcludedArea == value) return;
		playerInExcludedArea = value;
		if (onTransition != null) onTransition.run();
	}
	private WorldPoint currentPlayerWorldPoint() {
		Player player = client.getLocalPlayer();
		if (player == null) return null;
		WorldView worldView = player.getWorldView();
		if (worldView != null && worldView.isTopLevel() && !worldView.isInstance()) {
			WorldPoint worldPoint = player.getWorldLocation();
			if (worldPoint != null) return worldPoint;
		}
		LocalPoint localPoint = player.getLocalLocation();
		if (localPoint == null) return null;
		return WorldPoint.fromLocalInstance(client, localPoint);
	}
	private static final class ExcludedAreas {
		private static final ExcludedArea[] VALUES = {
				new ExcludedArea(2367, 5053, 2432, 5119, 0),			// TzHaar Fight Cave
				new ExcludedArea(2256, 5328, 2286, 5359, 0),			// Inferno
				new ExcludedArea(3500, 5100, 4000, 5440, 0, 1),		// Tombs of Amascut
				new ExcludedArea(3136, 4216, 3366, 4474, 0, 1, 2),	// Theatre of Blood
				new ExcludedArea(2215, 5935, 2325, 6035, 0, 1, 2),	// Hallowed Sepulchre Floor 1
				new ExcludedArea(2475, 5935, 2585, 6035, 0, 1, 2),	// Hallowed Sepulchre Floor 2
				new ExcludedArea(2225, 5795, 2575, 5915, 0, 1, 2),	// Hallowed Sepulchre Floors 3-5
				new ExcludedArea(3150, 5690, 3380, 5770, 0, 1, 2),	// Chambers of Xeric
				new ExcludedArea(3250, 5120, 3370, 5700, 0, 1, 2)	// Chambers of Xeric
		};
	}
	static final class ExcludedArea {
		private final int minX;
		private final int minY;
		private final int maxX;
		private final int maxY;
		private final int planeMask;
		@SuppressWarnings("SameParameterValue")
		ExcludedArea(int minX, int minY, int maxX, int maxY, int... planes) {
			this.minX = minX;
			this.minY = minY;
			this.maxX = maxX;
			this.maxY = maxY;
			int mask = 0;
			for (int plane : planes) { if (plane >= 0 && plane < Integer.SIZE) mask |= 1 << plane; }
			this.planeMask = mask;
		}
		boolean contains(WorldPoint point) {
			int plane = point.getPlane();
			return plane >= 0 && plane < Integer.SIZE && (planeMask & (1 << plane)) != 0 &&
					point.getX() >= minX && point.getX() <= maxX &&
					point.getY() >= minY && point.getY() <= maxY;
		}
	}
}

package com.fogofwar.config;
import lombok.Getter;
public enum ActorCutoutLimit {
	NONE("None", 0),
	LIMIT_16("16", 16),
	LIMIT_32("32", 32),
	LIMIT_48("48", 48),
	LIMIT_64("64", 64),
	LIMIT_96("96", 96),
	LIMIT_128("128", 128),
	LIMIT_192("192", 192),
	LIMIT_224("224", 224),
	ALL("All", Integer.MAX_VALUE);
	private final String name;
	@Getter
	private final int limit;
	ActorCutoutLimit(String name, int limit) {
		this.name = name;
		this.limit = limit;
	}
	public boolean isEnabled() { return limit > 0; }
	@Override
	public String toString() { return name; }
}

package com.fogofwar.config;
public enum FadingPlayerMode {
	OFF("Off"),
	WORLD("World"),
	MINIMAP("Minimap"),
	BOTH("World + minimap");
	private final String name;
	FadingPlayerMode(String name) { this.name = name; }
	public boolean showsWorld() { return this == WORLD || this == BOTH; }
	public boolean showsMinimap() { return this == MINIMAP || this == BOTH; }
	@Override
	public String toString() { return name; }
}

package com.fogofwar.config;
public enum FogDisplayMode {
	OFF(false, false, "Off"),
	FOG(true, false, "Fog"),
	BORDER(false, true, "Border"),
	BOTH(true, true, "Fog + border");
	private final boolean fog;
	private final boolean border;
	private final String name;
	FogDisplayMode(boolean fog, boolean border, String name) {
		this.fog = fog;
		this.border = border;
		this.name = name;
	}
	public boolean showsFog() { return fog; }
	public boolean showsBorder() { return border; }
	public boolean isEnabled() { return fog || border; }
	@Override
	public String toString() { return name; }
}

package com.fogofwar.config;
import net.runelite.client.config.*;
import java.awt.*;
@ConfigGroup(FogOfWarConfig.CONFIG_GROUP)
@SuppressWarnings("SameReturnValue")
public interface FogOfWarConfig extends Config {
	String CONFIG_GROUP = "fogofwar";
	@ConfigItem(
			keyName = "disableDuringCutscenes",
			name = "Disable during cutscenes",
			description = "Suspend all plugin overlays and tracking during cutscenes.",
			position = 0
	)
	default boolean disableDuringCutscenes() { return true; }
	@ConfigItem(
			keyName = "onlyInWilderness",
			name = "Only in Wilderness",
			description = "Hide all plugin overlays outside the Wilderness.",
			position = 1
	)
	default boolean onlyInWilderness() { return false; }
	@ConfigItem(
			keyName = "disableWhileSailing",
			name = "Disable while Sailing",
			description = "Hide world, minimap, and fading overlays while Sailing.",
			position = 2
	)
	default boolean disableWhileSailing() { return false; }
	@ConfigItem(
			keyName = "showLandAreaWhileSailing",
			name = "Show land area while Sailing",
			description = "Show the smaller land actor render area while Sailing.",
			position = 3
	)
	default boolean showLandAreaWhileSailing() { return false; }
	@ConfigSection(
			name = "World",
			description = "Settings for the world overlay",
			position = 4
	)
	String worldSection = "worldSection";
	@ConfigItem(
			keyName = "worldDisplayMode",
			name = "World display",
			description = "Choose what to draw in the world view.",
			section = worldSection,
			position = 0
	)
	default FogDisplayMode worldDisplayMode() { return FogDisplayMode.FOG; }
	@Alpha
	@ConfigItem(
			keyName = "worldFogColour",
			name = "Fog colour",
			description = "Colour of the world fog.",
			section = worldSection,
			position = 1
	)
	default Color worldFogColour() { return new Color(0, 0, 0, 125); }
	@Alpha
	@ConfigItem(
			keyName = "worldBorderColour",
			name = "Border colour",
			description = "Colour of the world render-distance border.",
			section = worldSection,
			position = 2
	)
	default Color worldBorderColour() { return new Color(0, 0, 0, 125); }
	@Range(min = 1, max = 16)
	@ConfigItem(
			keyName = "worldBorderThickness",
			name = "Border thickness",
			description = "Width of the world render-distance border.",
			section = worldSection,
			position = 3
	)
	default int worldBorderThickness() { return 1; }
	@ConfigItem(
			keyName = "actorCutoutLimit",
			name = "Actor cutouts",
			description = "Keep visible players and NPCs uncovered by world fog. Higher values cost more performance.",
			section = worldSection,
			position = 4
	)
	default ActorCutoutLimit actorCutoutLimit() { return ActorCutoutLimit.LIMIT_64; }
	@ConfigSection(
			name = "Minimap",
			description = "Settings for the minimap overlay",
			position = 5
	)
	String minimapSection = "minimapSection";
	@ConfigItem(
			keyName = "minimapDisplayMode",
			name = "Minimap display",
			description = "Choose what to draw on the minimap.",
			section = minimapSection,
			position = 0
	)
	default FogDisplayMode minimapDisplayMode() { return FogDisplayMode.FOG; }
	@Alpha
	@ConfigItem(
			keyName = "minimapFogColour",
			name = "Fog colour",
			description = "Colour of the minimap fog.",
			section = minimapSection,
			position = 1
	)
	default Color minimapFogColour() { return new Color(0, 0, 0, 125); }
	@Alpha
	@ConfigItem(
			keyName = "minimapBorderColour",
			name = "Border colour",
			description = "Colour of the minimap render-distance border.",
			section = minimapSection,
			position = 2
	)
	default Color minimapBorderColour() { return new Color(0, 0, 0, 125); }
	@Range(min = 1, max = 16)
	@ConfigItem(
			keyName = "minimapBorderThickness",
			name = "Border thickness",
			description = "Width of the minimap render-distance border.",
			section = minimapSection,
			position = 3
	)
	default int minimapBorderThickness() { return 1; }
	@ConfigSection(
			name = "Fading Players",
			description = "Settings for marking players that leave render distance",
			position = 6
	)
	String fadingPlayerSection = "fadingPlayerSection";
	@ConfigItem(
			keyName = "playerFadeMarkerMode",
			name = "Player fade markers",
			description = "Show fading markers where players leave render distance.",
			section = fadingPlayerSection,
			position = 0
	)
	default FadingPlayerMode playerFadeMarkerMode() { return FadingPlayerMode.OFF; }
	@Alpha
	@ConfigItem(
			keyName = "fadeMarkerColour",
			name = "Marker colour",
			description = "Colour of player fade markers.",
			section = fadingPlayerSection,
			position = 1
	)
	default Color fadeMarkerColour() { return new Color(255, 0, 0, 150); }
	@Range(min = 1, max = 16)
	@ConfigItem(
			keyName = "fadeDurationTicks",
			name = "Fade duration",
			description = "Ticks before fade markers disappear.",
			section = fadingPlayerSection,
			position = 2
	)
	default int fadeDurationTicks() { return 2; }
	@ConfigItem(
			keyName = "onlyFadeAtRenderEdge",
			name = "Render near edge only",
			description = "Only mark players that disappear near the render-distance edge.",
			section = fadingPlayerSection,
			position = 3
	)
	default boolean onlyFadeAtRenderEdge() { return true; }
	@ConfigItem(
			keyName = "predictMovement",
			name = "Predict movement",
			description = "Move fade markers using the player's last known movement.",
			section = fadingPlayerSection,
			position = 4
	)
	default boolean predictMovement() { return true; }
	@ConfigItem(
			keyName = "showFadeMarkerNames",
			name = "Show player names",
			description = "Show names on world fade markers.",
			section = fadingPlayerSection,
			position = 5
	)
	default boolean showFadeMarkerNames() { return true; }
	@ConfigSection(
			name = "Tweaks",
			description = "Advanced settings for experimental features.",
			position = 7,
			closedByDefault = true
	)
	String tweaksSection = "tweaksSection";
	@Range(min = 1, max = 64)
	@ConfigItem(
			keyName = "landRenderDistance",
			name = "Land actor distance",
			description = "Land actor render distance used by the overlay. Does not change the game's render distance.",
			section = tweaksSection,
			position = 0
	)
	default int landRenderDistance() { return 15; }
	@Range(min = 1, max = 64)
	@ConfigItem(
			keyName = "sailingRenderDistance",
			name = "Sea actor distance",
			description = "Sea actor render distance used by the overlay. Does not change the game's render distance.",
			section = tweaksSection,
			position = 1
	)
	default int sailingRenderDistance() { return 30; }
	@ConfigItem(
			keyName = "debugOverlayEnabled",
			name = "Debug overlay",
			description = "Show current plane.",
			section = tweaksSection,
			position = 2
	)
	default boolean debugOverlayEnabled() { return false; }
}

package com.fogofwar.coord;
import net.runelite.api.Actor;
import net.runelite.api.Player;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldEntityConfig;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
public final class WorldEntityCoords {
	private static final int SHIP_ENTITY_CATEGORY = 2395;
	private WorldEntityCoords() {}
	public static WorldEntity getWorldEntity(WorldView sourceWorldView, WorldView topWorldView) {
		if (sourceWorldView == null || topWorldView == null || sourceWorldView.isTopLevel()) return null;
		return topWorldView.worldEntities().byIndex(sourceWorldView.getId());
	}
	public static WorldEntity getPlayerWorldEntity(Player player, WorldView topWorldView) {
		if (player == null) return null;
		return getWorldEntity(player.getWorldView(), topWorldView);
	}
	public static WorldPoint toTopLevelWorldPoint(WorldView topWorldView, LocalPoint localPoint) {
		if (topWorldView == null || localPoint == null) return null;
		return WorldPoint.fromLocal(topWorldView, localPoint.getX(), localPoint.getY(), topWorldView.getPlane());
	}
	private static WorldEntity getPlayerShip(Player player, WorldView topWorldView) {
		WorldEntity worldEntity = getPlayerWorldEntity(player, topWorldView);
		return isShip(worldEntity) ? worldEntity : null;
	}
	public static boolean isPlayerOnShip(Player player, WorldView topWorldView) { return getPlayerShip(player, topWorldView) != null; }
	public static boolean isShip(WorldEntity worldEntity) {
		WorldEntityConfig config = worldEntity != null ? worldEntity.getConfig() : null;
		return config != null && config.getCategory() == SHIP_ENTITY_CATEGORY;
	}
	public static ResolvedPoint resolveTopLevel(Actor actor, WorldView sourceWorldView, WorldView topWorldView, WorldEntity worldEntity) {
		if (actor == null || topWorldView == null) return null;
		if (sourceWorldView == null) sourceWorldView = actor.getWorldView();
		if (sourceWorldView == null) return null;
		WorldPoint worldPoint = actor.getWorldLocation();
		LocalPoint localPoint = actor.getLocalLocation();
		if (sourceWorldView.isTopLevel()) {
			if (worldPoint == null) return null;
			if (localPoint == null) localPoint = LocalPoint.fromWorld(topWorldView, worldPoint);
			return localPoint != null ? new ResolvedPoint(worldPoint, localPoint) : null;
		}
		if (worldEntity == null) worldEntity = getWorldEntity(sourceWorldView, topWorldView);
		if (worldEntity == null) return null;
		if (localPoint == null && worldPoint != null) localPoint = LocalPoint.fromWorld(sourceWorldView, worldPoint);
		if (localPoint == null) return null;
		LocalPoint topLocalPoint = worldEntity.transformToMainWorld(localPoint);
		WorldPoint topWorldPoint = toTopLevelWorldPoint(topWorldView, topLocalPoint);
		return topWorldPoint != null ? new ResolvedPoint(topWorldPoint, topLocalPoint) : null;
	}
	public static WorldPoint playerToTopLevel(Player player, WorldView sourceWorldView, WorldView topWorldView) {
		if (player == null || topWorldView == null) return null;
		if (sourceWorldView == null) sourceWorldView = player.getWorldView();
		if (sourceWorldView == null) return null;
		WorldPoint worldPoint = player.getWorldLocation();
		LocalPoint localPoint = player.getLocalLocation();
		if (sourceWorldView.isTopLevel()) {
			if (worldPoint == null) return null;
			return localPoint != null || LocalPoint.fromWorld(topWorldView, worldPoint) != null ? worldPoint : null;
		}
		WorldEntity worldEntity = getWorldEntity(sourceWorldView, topWorldView);
		if (worldEntity == null) return null;
		if (localPoint == null && worldPoint != null) localPoint = LocalPoint.fromWorld(sourceWorldView, worldPoint);
		return localPoint != null ? toTopLevelWorldPoint(topWorldView, worldEntity.transformToMainWorld(localPoint)) : null;
	}
	public static final class ResolvedPoint {
		public final WorldPoint worldPoint;
		public final LocalPoint localPoint;
		private ResolvedPoint(WorldPoint worldPoint, LocalPoint localPoint) {
			this.worldPoint = worldPoint;
			this.localPoint = localPoint;
		}
	}
}

package com.fogofwar.debug;
import com.fogofwar.config.FogOfWarConfig;
import com.fogofwar.coord.WorldEntityCoords;
import com.fogofwar.render.RenderCenterProvider;
import com.fogofwar.state.ClientState;
import net.runelite.api.Player;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldEntityConfig;
import net.runelite.api.WorldView;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import javax.inject.Inject;
import java.awt.Dimension;
import java.awt.Graphics2D;
public final class DebugOverlay extends OverlayPanel {
	private final FogOfWarConfig config;
	private final ClientState clientState;
	private final RenderCenterProvider renderCenterProvider;
	private LineComponent planeLine;
	private LineComponent worldViewLine;
	private LineComponent entityLine;
	private LineComponent categoryLine;
	private int plane = Integer.MIN_VALUE;
	private int worldViewId = Integer.MIN_VALUE;
	private int entityId = Integer.MIN_VALUE;
	private int entityCategory = Integer.MIN_VALUE;
	@Inject
	public DebugOverlay(FogOfWarConfig config, ClientState clientState, RenderCenterProvider renderCenterProvider) {
		this.config = config;
		this.clientState = clientState;
		this.renderCenterProvider = renderCenterProvider;
		setPosition(OverlayPosition.TOP_LEFT);
	}
	public void clearCaches() {
		panelComponent.getChildren().clear();
		planeLine = worldViewLine = entityLine = categoryLine = null;
		plane = worldViewId = entityId = entityCategory = Integer.MIN_VALUE;
		setClearChildren(true);
	}
	@Override
	public Dimension render(Graphics2D graphics) {
		if (!config.debugOverlayEnabled()) return null;
		Player localPlayer = clientState.getLocalPlayerIfReady();
		if (localPlayer == null) return null;
		if (planeLine == null) initLines();
		WorldView wv = localPlayer.getWorldView();
		WorldView topWorldView = wv != null && wv.isTopLevel() ? wv : renderCenterProvider.getTopLevelWorldView(localPlayer);
		if (wv == null) wv = topWorldView;
		WorldEntityConfig entityConfig = getWorldEntityConfig(wv, topWorldView);
		plane = update(planeLine, plane, wv != null ? wv.getPlane() : Integer.MIN_VALUE);
		worldViewId = update(worldViewLine, worldViewId, wv != null ? wv.getId() : Integer.MIN_VALUE);
		entityId = update(entityLine, entityId, entityConfig != null ? entityConfig.getId() : Integer.MIN_VALUE);
		entityCategory = update(categoryLine, entityCategory, entityConfig != null ? entityConfig.getCategory() : Integer.MIN_VALUE);
		return super.render(graphics);
	}
	private void initLines() {
		planeLine = line("Current plane:");
		worldViewLine = line("World view ID:");
		entityLine = line("Entity ID:");
		categoryLine = line("Entity category:");
		setClearChildren(false);
		panelComponent.getChildren().add(planeLine);
		panelComponent.getChildren().add(worldViewLine);
		panelComponent.getChildren().add(entityLine);
		panelComponent.getChildren().add(categoryLine);
	}
	private WorldEntityConfig getWorldEntityConfig(WorldView worldView, WorldView topWorldView) {
		WorldEntity worldEntity = WorldEntityCoords.getWorldEntity(worldView, topWorldView);
		return worldEntity != null ? worldEntity.getConfig() : null;
	}
	private static LineComponent line(String left) { return LineComponent.builder().left(left).right("?").build(); }
	private static int update(LineComponent line, int previous, int value) {
		if (previous != value) line.setRight(value == Integer.MIN_VALUE ? "?" : Integer.toString(value));
		return value;
	}
}

package com.fogofwar.fade;
import com.fogofwar.config.FogOfWarConfig;
import com.fogofwar.render.RenderCenter;
import com.fogofwar.render.RenderCenterProvider;
import com.fogofwar.state.ClientState;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import java.awt.Dimension;
import java.awt.Color;
import java.awt.Graphics2D;
import java.util.Collection;
abstract class AbstractFadingPlayerOverlay extends Overlay {
	protected final Client client;
	protected final FogOfWarConfig config;
	private final FadingPlayerManager manager;
	private final ClientState clientState;
	private final RenderCenterProvider renderCenterProvider;
	AbstractFadingPlayerOverlay(Client client, FogOfWarConfig config, FadingPlayerManager manager, ClientState clientState, RenderCenterProvider renderCenterProvider, OverlayLayer layer) {
		this.client = client;
		this.config = config;
		this.manager = manager;
		this.clientState = clientState;
		this.renderCenterProvider = renderCenterProvider;
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(Overlay.PRIORITY_HIGH);
		setLayer(layer);
	}
	@Override
	public Dimension render(Graphics2D graphics) {
		if (!showsMarker()) return null;
		Player localPlayer = clientState.getLocalPlayerIfReady();
		if (localPlayer == null) return null;
		Collection<FadingPlayer> fadingPlayers = manager.getFadingPlayers().values();
		if (fadingPlayers.isEmpty()) return null;
		RenderCenter rc = renderCenterProvider.get(localPlayer);
		if (rc == null) return null;
		WorldView wv = rc.getWorldView();
		return renderPlayers(graphics, wv, fadingPlayers);
	}
	Dimension renderPlayers(Graphics2D graphics, WorldView wv, Collection<FadingPlayer> fadingPlayers) {
		Color base = config.fadeMarkerColour();
		int duration = config.fadeDurationTicks();
		for (FadingPlayer fadingPlayer : fadingPlayers) renderPlayer(graphics, wv, fadingPlayer, base, duration);
		return null;
	}
	private void renderPlayer(Graphics2D graphics, WorldView wv, FadingPlayer fadingPlayer, Color base, int duration) {
		LocalPoint lp = fadingPlayer.getLocalPoint(wv);
		if (lp == null) return;
		renderPlayer(graphics, lp, fadingPlayer, base, duration);
	}
	abstract boolean showsMarker();
	abstract void renderPlayer(Graphics2D graphics, LocalPoint lp, FadingPlayer fadingPlayer, Color base, int duration);
}

package com.fogofwar.fade;
import lombok.Getter;
import lombok.Setter;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import java.awt.Color;
@Getter
class FadingPlayer {
	private final Player player;
	@Setter
	private WorldPoint markerLocation;
	private final WorldPoint velocity;
	private final int renderDistance;
	@Setter
	private int ticksSinceDisappeared = 0;
	private int cachedTick = Integer.MIN_VALUE;
	private int cachedFadeDuration = Integer.MIN_VALUE;
	private int cachedBaseRgb;
	private Color cachedColor;
	private Color cachedDarkerColor;
	private WorldView cachedWorldView;
	private WorldPoint cachedLocalMarker;
	private LocalPoint cachedLocalPoint;
	FadingPlayer(Player player, WorldPoint velocity, WorldPoint initialLocation, int renderDistance) {
		this.player = player;
		this.velocity = velocity;
		this.markerLocation = initialLocation;
		this.renderDistance = renderDistance;
	}
	Color getColor(Color base, int duration) {
		int baseRgb = base.getRGB();
		if (cachedColor != null && cachedTick == ticksSinceDisappeared && cachedFadeDuration == duration && cachedBaseRgb == baseRgb) return cachedColor;
		float d = Math.max(1, duration);
		float o = (d - ticksSinceDisappeared) / d;
		cachedColor = new Color(base.getRed() / 255f, base.getGreen() / 255f, base.getBlue() / 255f, (base.getAlpha() / 255f) * o);
		cachedDarkerColor = null;
		cachedTick = ticksSinceDisappeared;
		cachedFadeDuration = duration;
		cachedBaseRgb = baseRgb;
		return cachedColor;
	}
	Color getDarkerColor(Color base, int duration) {
		getColor(base, duration);
		if (cachedDarkerColor == null) cachedDarkerColor = cachedColor.darker();
		return cachedDarkerColor;
	}
	LocalPoint getLocalPoint(WorldView worldView) {
		if (cachedWorldView != worldView || cachedLocalMarker != markerLocation) {
			cachedWorldView = worldView;
			cachedLocalMarker = markerLocation;
			cachedLocalPoint = LocalPoint.fromWorld(worldView, markerLocation);
		}
		return cachedLocalPoint;
	}
}

package com.fogofwar.fade;
import com.fogofwar.config.FogOfWarConfig;
import com.fogofwar.area.AreaExclusionManager;
import com.fogofwar.coord.WorldEntityCoords;
import com.fogofwar.lifecycle.LifecycleComponent;
import com.fogofwar.render.RenderCenterProvider;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameTick;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Collections;
import java.util.Map;
import java.util.Set;
@Singleton
public class FadingPlayerManager extends LifecycleComponent {
	private static final Map<Player, FadingPlayer> EMPTY_FADING = Collections.emptyMap();
	private static final Set<String> EMPTY_NAMES = Collections.emptySet();
	private final Client client;
	private final FogOfWarConfig config;
	private final AreaExclusionManager areaExclusionManager;
	private final RenderCenterProvider renderCenterProvider;
	@Getter
	private Map<Player, FadingPlayer> fadingPlayers = EMPTY_FADING;
	private Map<Player, TrackedPlayer> lastTickPlayerLocations = Collections.emptyMap();
	private Map<Player, TrackedPlayer> twoTicksAgoPlayerLocations = Collections.emptyMap();
	private Map<Player, TrackedPlayer> currentPlayerLocations = Collections.emptyMap();
	private Set<String> currentPlayerNames = EMPTY_NAMES;
	@Inject
	public FadingPlayerManager(Client client, FogOfWarConfig config, EventBus eventBus, AreaExclusionManager areaExclusionManager, RenderCenterProvider renderCenterProvider) {
		super(eventBus);
		this.client = client;
		this.config = config;
		this.areaExclusionManager = areaExclusionManager;
		this.renderCenterProvider = renderCenterProvider;
	}
	@Override
	protected void onStart() {
		fadingPlayers = EMPTY_FADING;
		lastTickPlayerLocations = new HashMap<>();
		twoTicksAgoPlayerLocations = new HashMap<>();
		currentPlayerLocations = new HashMap<>();
		currentPlayerNames = EMPTY_NAMES;
	}
	@Override
	protected void onStop() {
		fadingPlayers = EMPTY_FADING;
		lastTickPlayerLocations = Collections.emptyMap();
		twoTicksAgoPlayerLocations = Collections.emptyMap();
		currentPlayerLocations = Collections.emptyMap();
		currentPlayerNames = EMPTY_NAMES;
	}
	@Subscribe
	@SuppressWarnings("unused")
	public void onGameTick(GameTick event) {
		if (client.getGameState() != GameState.LOGGED_IN) {
			clearAllTracking();
			return;
		}
		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null) {
			clearAllTracking();
			return;
		}
		WorldView worldView = renderCenterProvider.getTopLevelWorldView(localPlayer);
		if (worldView == null) {
			clearAllTracking();
			return;
		}
		WorldPoint localPlayerLocation = WorldEntityCoords.playerToTopLevel(localPlayer, null, worldView);
		if (localPlayerLocation == null) {
			clearAllTracking();
			return;
		}
		if (areaExclusionManager.isPlayerInExcludedArea()) {
			clearAllTracking();
			return;
		}
		boolean onWorldEntity = WorldEntityCoords.isPlayerOnShip(localPlayer, worldView);
		if (config.disableWhileSailing() && onWorldEntity) {
			clearAllTracking();
			return;
		}
		int fadeDuration = config.fadeDurationTicks();
		boolean extrapolate = config.predictMovement();
		boolean onlyAtLimit = config.onlyFadeAtRenderEdge();
		handleFadingPlayers(fadeDuration, extrapolate, localPlayerLocation);
		updatePlayerTracking(extrapolate, onlyAtLimit, localPlayer, worldView, localPlayerLocation, onWorldEntity);
	}
	private void clearAllTracking() {
		fadingPlayers = EMPTY_FADING;
		lastTickPlayerLocations.clear();
		twoTicksAgoPlayerLocations.clear();
		currentPlayerLocations.clear();
		currentPlayerNames = EMPTY_NAMES;
	}
	private void handleFadingPlayers(int fadeDuration, boolean extrapolate, WorldPoint localPlayerLocation) {
		if (fadingPlayers == EMPTY_FADING) return;
		fadingPlayers.entrySet().removeIf(entry -> {
			FadingPlayer fp = entry.getValue();
			fp.setTicksSinceDisappeared(fp.getTicksSinceDisappeared() + 1);
			if (fp.getTicksSinceDisappeared() >= fadeDuration) return true;
			WorldPoint markerLocation = fp.getMarkerLocation();
			if (fp.getTicksSinceDisappeared() > 1 && markerLocation.distanceTo(localPlayerLocation) <= fp.getRenderDistance()) return true;
			WorldPoint velocity = fp.getVelocity();
			if (extrapolate && velocity != null && (velocity.getX() != 0 || velocity.getY() != 0)) {
				fp.setMarkerLocation(new WorldPoint(
						markerLocation.getX() + velocity.getX(),
						markerLocation.getY() + velocity.getY(),
						markerLocation.getPlane()));
			}
			return false;
		});
		if (fadingPlayers.isEmpty()) fadingPlayers = EMPTY_FADING;
	}
	private void updatePlayerTracking(boolean extrapolate, boolean onlyAtLimit, Player localPlayer, WorldView worldView, WorldPoint localPlayerLocation, boolean onWorldEntity) {
		currentPlayerLocations.clear();
		boolean collectNames = !fadingPlayers.isEmpty();
		if (collectNames) {
			if (currentPlayerNames == EMPTY_NAMES) currentPlayerNames = new HashSet<>();
			else currentPlayerNames.clear();
		} else currentPlayerNames = EMPTY_NAMES;
		int landRenderDistance = config.landRenderDistance();
		trackPlayers(localPlayer, worldView, worldView, landRenderDistance, collectNames);
		int boatRenderDistance = onWorldEntity ? config.sailingRenderDistance() : landRenderDistance;
		for (WorldEntity worldEntity : worldView.worldEntities()) {
			if (worldEntity == null) continue;
			WorldView entityWorldView = worldEntity.getWorldView();
			if (entityWorldView == null) continue;
			trackPlayers(localPlayer, entityWorldView, worldView, boatRenderDistance, collectNames);
		}
		boolean needsVelocity = onlyAtLimit || extrapolate;
		for (Map.Entry<Player, TrackedPlayer> entry : lastTickPlayerLocations.entrySet()) {
			Player player = entry.getKey();
			if (currentPlayerLocations.containsKey(player)) continue;
			if (fadingPlayers.containsKey(player)) continue;
			TrackedPlayer lastTickPlayer = entry.getValue();
			WorldPoint lastLocation = lastTickPlayer.getLocation();
			if (lastLocation == null) continue;
			int renderDistance = lastTickPlayer.getRenderDistance();
			WorldPoint velocity = null;
			boolean nearRenderLimit = false;
			if (needsVelocity) {
				TrackedPlayer twoTicksAgoPlayer = twoTicksAgoPlayerLocations.get(player);
				WorldPoint twoTicksAgoLocation = twoTicksAgoPlayer != null ? twoTicksAgoPlayer.getLocation() : null;
				velocity = FadingPlayerPredictor.getVelocity(lastLocation, twoTicksAgoLocation);
				nearRenderLimit = FadingPlayerPredictor.isNearRenderLimit(lastLocation, localPlayerLocation, velocity, renderDistance);
			}
			if (onlyAtLimit && !nearRenderLimit) continue;
			WorldPoint initialFadeLocation = extrapolate ? FadingPlayerPredictor.getInitialFadeLocation(lastLocation, localPlayerLocation, velocity, true, renderDistance, nearRenderLimit) : lastLocation;
			if (fadingPlayers == EMPTY_FADING) fadingPlayers = new HashMap<>();
			fadingPlayers.put(player, new FadingPlayer(player, velocity, initialFadeLocation, renderDistance));
		}
		Map<Player, TrackedPlayer> tmp = twoTicksAgoPlayerLocations;
		twoTicksAgoPlayerLocations = lastTickPlayerLocations;
		lastTickPlayerLocations = currentPlayerLocations;
		currentPlayerLocations = tmp;
		if (!collectNames && !fadingPlayers.isEmpty()) collectCurrentPlayerNames(localPlayer, worldView);
		if (fadingPlayers != EMPTY_FADING) fadingPlayers.entrySet().removeIf(entry -> {
			String name = entry.getKey().getName();
			return name != null && currentPlayerNames.contains(name);
		});
		if (fadingPlayers.isEmpty()) fadingPlayers = EMPTY_FADING;
	}
	private void trackPlayers(Player localPlayer, WorldView worldView, WorldView topWorldView, int renderDistance, boolean collectNames) {
		for (Player player : worldView.players()) {
			if (player == null || player == localPlayer) continue;
			WorldPoint playerLocation = WorldEntityCoords.playerToTopLevel(player, worldView, topWorldView);
			if (playerLocation != null) currentPlayerLocations.put(player, new TrackedPlayer(playerLocation, renderDistance));
			if (collectNames) addPlayerName(player);
		}
	}
	private void collectCurrentPlayerNames(Player localPlayer, WorldView worldView) {
		if (currentPlayerNames == EMPTY_NAMES) currentPlayerNames = new HashSet<>();
		else currentPlayerNames.clear();
		collectPlayerNames(localPlayer, worldView);
		for (WorldEntity worldEntity : worldView.worldEntities()) {
			if (worldEntity == null) continue;
			WorldView entityWorldView = worldEntity.getWorldView();
			if (entityWorldView != null) collectPlayerNames(localPlayer, entityWorldView);
		}
	}
	private void collectPlayerNames(Player localPlayer, WorldView worldView) {
		for (Player player : worldView.players()) { if (player != null && player != localPlayer) addPlayerName(player); }
	}
	private void addPlayerName(Player player) {
		String name = player.getName();
		if (name != null) currentPlayerNames.add(name);
	}
	@Getter
	private static class TrackedPlayer {
		private final WorldPoint location;
		private final int renderDistance;
		private TrackedPlayer(WorldPoint location, int renderDistance) {
			this.location = location;
			this.renderDistance = renderDistance;
		}
	}
}

package com.fogofwar.fade;
import com.fogofwar.config.FogOfWarConfig;
import com.fogofwar.render.RenderCenterProvider;
import com.fogofwar.render.minimap.MinimapClipProvider;
import com.fogofwar.state.ClientState;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.OverlayLayer;
import javax.inject.Inject;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Shape;
import java.util.Collection;
public class FadingPlayerMinimapOverlay extends AbstractFadingPlayerOverlay {
	private static final int DOT_SIZE = 4;
	private final MinimapClipProvider clipProvider;
	@Inject
	protected FadingPlayerMinimapOverlay(Client client, FogOfWarConfig config, ClientState clientState, FadingPlayerManager manager, MinimapClipProvider clipProvider, RenderCenterProvider renderCenterProvider) {
		super(client, config, manager, clientState, renderCenterProvider, OverlayLayer.ABOVE_WIDGETS);
		this.clipProvider = clipProvider;
	}
	public void clearCaches() { clipProvider.clearCaches(); }
	@Override
	boolean showsMarker() { return config.playerFadeMarkerMode().showsMinimap(); }
	@Override
	Dimension renderPlayers(Graphics2D graphics, WorldView wv, Collection<FadingPlayer> fadingPlayers) {
		Widget minimapWidget = clipProvider.getMinimapWidget();
		if (minimapWidget == null || minimapWidget.isHidden()) return null;
		Shape oldClip = graphics.getClip();
		graphics.clip(clipProvider.getClipShape(minimapWidget));
		try {
			return super.renderPlayers(graphics, wv, fadingPlayers);
		} finally { graphics.setClip(oldClip); }
	}
	@Override
	void renderPlayer(Graphics2D graphics, LocalPoint lp, FadingPlayer fadingPlayer, Color base, int duration) {
		Color color = fadingPlayer.getColor(base, duration);
		if (color.getAlpha() == 0) return;
		Point mp = Perspective.localToMinimap(client, lp);
		if (mp == null) return;
		Color shadedColor = fadingPlayer.getDarkerColor(base, duration);
		int x = mp.getX() - DOT_SIZE / 2;
		int y = mp.getY() - DOT_SIZE / 2 + 1;
		graphics.setColor(shadedColor);
		graphics.fillArc(x, y, DOT_SIZE, DOT_SIZE, 180, 180);
		graphics.setColor(color);
		graphics.fillArc(x, y, DOT_SIZE, DOT_SIZE, 0, 180);
	}
}

package com.fogofwar.fade;
import com.fogofwar.config.FogOfWarConfig;
