import javax.inject.Inject;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.util.Collection;
public class FadingPlayerOverlay extends AbstractFadingPlayerOverlay {
	private boolean showNames;
	@Inject
	protected FadingPlayerOverlay(Client client, FogOfWarConfig config, FadingPlayerManager manager, ClientState clientState, RenderCenterProvider renderCenterProvider) {
		super(client, config, manager, clientState, renderCenterProvider, OverlayLayer.ABOVE_SCENE);
	}
	@Override
	boolean showsMarker() { return config.playerFadeMarkerMode().showsWorld(); }
	@Override
	Dimension renderPlayers(Graphics2D graphics, WorldView wv, Collection<FadingPlayer> fadingPlayers) {
		showNames = config.showFadeMarkerNames();
		return super.renderPlayers(graphics, wv, fadingPlayers);
	}
	@Override
	void renderPlayer(Graphics2D graphics, LocalPoint lp, FadingPlayer fadingPlayer, Color base, int duration) {
		Color color = fadingPlayer.getColor(base, duration);
		if (color.getAlpha() == 0 && !showNames) return;
		Polygon poly = Perspective.getCanvasTilePoly(client, lp);
		if (poly == null) return;
		if (color.getAlpha() > 0) {
			graphics.setColor(color);
			graphics.fill(poly);
		}
		if (showNames) {
			String name = fadingPlayer.getPlayer().getName();
			if (name != null) {
				Point textLoc = Perspective.getCanvasTextLocation(client, graphics, lp, name, 0);
				if (textLoc != null) OverlayUtil.renderTextLocation(graphics, textLoc, name, color);
			}
		}
	}
}

package com.fogofwar.fade;
import net.runelite.api.coords.WorldPoint;
final class FadingPlayerPredictor {
	private static final WorldPoint ZERO_VELOCITY = new WorldPoint(0, 0, 0);
	private FadingPlayerPredictor() {}
	static WorldPoint getVelocity(WorldPoint lastLocation, WorldPoint twoTicksAgoLocation) {
		return twoTicksAgoLocation != null
				? new WorldPoint(lastLocation.getX() - twoTicksAgoLocation.getX(), lastLocation.getY() - twoTicksAgoLocation.getY(), 0)
				: ZERO_VELOCITY;
	}
	static boolean isNearRenderLimit(WorldPoint lastLocation, WorldPoint localPlayerLocation, WorldPoint velocity, int renderDistance) {
		return isAtRenderLimit(lastLocation, localPlayerLocation, renderDistance) || isRunningNearLimit(lastLocation, localPlayerLocation, velocity, renderDistance);
	}
	static WorldPoint getInitialFadeLocation(WorldPoint lastLocation, WorldPoint localPlayerLocation, WorldPoint velocity, boolean extrapolate, int renderDistance, boolean nearRenderLimit) {
		if (!extrapolate) return lastLocation;
		int dx = lastLocation.getX() - localPlayerLocation.getX();
		int dy = lastLocation.getY() - localPlayerLocation.getY();
		boolean onXEdge = Math.abs(dx) >= renderDistance - 1;
		boolean onYEdge = Math.abs(dy) >= renderDistance - 1;
		WorldPoint predictedNextLocation = new WorldPoint(lastLocation.getX() + velocity.getX(), lastLocation.getY() + velocity.getY(), lastLocation.getPlane());
		boolean isMovingIntoRenderArea = (onXEdge && dx * velocity.getX() < 0) || (onYEdge && dy * velocity.getY() < 0);
		if (isMovingIntoRenderArea) {
			int pushX = onXEdge ? Integer.signum(dx) : 0;
			int pushY = onYEdge ? Integer.signum(dy) : 0;
			return new WorldPoint(predictedNextLocation.getX() + pushX, predictedNextLocation.getY() + pushY, predictedNextLocation.getPlane());
		}
		WorldPoint initialFadeLocation = predictedNextLocation;
		if (nearRenderLimit) {
			int pushX = 0, pushY = 0;
			if (Math.abs(dx) > Math.abs(dy)) pushX = Integer.signum(dx);
			else if (Math.abs(dy) > Math.abs(dx)) pushY = Integer.signum(dy);
			else { pushX = Integer.signum(dx); pushY = Integer.signum(dy); }
			if ((pushX != 0 || pushY != 0) && predictedNextLocation.getPlane() == localPlayerLocation.getPlane()) {
				int x = predictedNextLocation.getX();
				int y = predictedNextLocation.getY();
				int lx = localPlayerLocation.getX();
				int ly = localPlayerLocation.getY();
				boolean moved = false;
				while (Math.max(Math.abs(x - lx), Math.abs(y - ly)) <= renderDistance) {
					x += pushX;
					y += pushY;
					moved = true;
				}
				if (moved) initialFadeLocation = new WorldPoint(x, y, predictedNextLocation.getPlane());
			}
		}
		return initialFadeLocation;
	}
	private static boolean isAtRenderLimit(WorldPoint lastLocation, WorldPoint localPlayerLocation, int renderDistance) {
		return lastLocation.distanceTo(localPlayerLocation) >= renderDistance - 1;
	}
	private static boolean isRunningNearLimit(WorldPoint lastLocation, WorldPoint localPlayerLocation, WorldPoint velocity, int renderDistance) {
		int velocityMagnitude = Math.abs(velocity.getX()) + Math.abs(velocity.getY());
		return lastLocation.distanceTo(localPlayerLocation) >= renderDistance - 2 && velocityMagnitude >= 2;
	}
}

package com.fogofwar.lifecycle;
import net.runelite.client.eventbus.EventBus;
public abstract class LifecycleComponent {
	private final EventBus eventBus;
	private boolean started;
	protected LifecycleComponent(EventBus eventBus) { this.eventBus = eventBus; }
	public final void start() {
		if (started) return;
		eventBus.register(this);
		started = true;
		onStart();
	}
	public final void stop() {
		if (!started) return;
		eventBus.unregister(this);
		started = false;
		onStop();
	}
	protected void onStart() {}
	protected void onStop() {}
}

package com.fogofwar.render;
import java.awt.geom.GeneralPath;
public final class BoundaryPathBuilder {
	public interface Strategy {
		GeneralPath coverage(GeneralPath path);
		boolean isValid(GeneralPath path);
		GeneralPath fallback(GeneralPath path);
	}
	private BoundaryPathBuilder() {}
	public static GeneralPath build(GeneralPath path, int[] x, int[] y, boolean[] visible, int count, double arcCenterX, double arcCenterY, double arcRadius, Strategy strategy) {
		GeneralPath result = buildPath(path, x, y, visible, count, arcCenterX, arcCenterY, arcRadius, strategy, false);
		if (strategy.isValid(result)) return result;
		result = buildPath(path, x, y, visible, count, arcCenterX, arcCenterY, arcRadius, strategy, true);
		if (strategy.isValid(result)) return result;
		return strategy.fallback(result);
	}
	private static GeneralPath buildPath(GeneralPath path, int[] x, int[] y, boolean[] visible, int count, double arcCenterX, double arcCenterY, double arcRadius, Strategy strategy, boolean reverseArc) {
		int firstVisible = -1;
		int visibleCount = 0;
		for (int i = 0; i < count; i++) {
			if (visible[i]) {
				if (firstVisible == -1) firstVisible = i;
				visibleCount++;
			}
		}
		if (visibleCount == 0) return strategy.coverage(path);
		path.reset();
		if (visibleCount == count) return buildCompletePath(path, x, y, count);
		path.moveTo(x[firstVisible], y[firstVisible]);
		for (int i = 0; i < count; i++) {
			int currentIndex = (firstVisible + i) % count;
			int nextIndex = (firstVisible + i + 1) % count;
			if (!visible[currentIndex]) continue;
			if (visible[nextIndex]) path.lineTo(x[nextIndex], y[nextIndex]);
			else {
				int nextVisibleIndex = findNextVisibleIndex(visible, currentIndex, count);
				if (nextVisibleIndex != -1) addArcToPath(path, x[currentIndex], y[currentIndex], x[nextVisibleIndex], y[nextVisibleIndex], arcCenterX, arcCenterY, arcRadius, reverseArc);
			}
		}
		path.closePath();
		return path;
	}
	private static GeneralPath buildCompletePath(GeneralPath path, int[] x, int[] y, int count) {
		path.moveTo(x[0], y[0]);
		for (int i = 1; i < count; i++) path.lineTo(x[i], y[i]);
		path.closePath();
		return path;
	}
	private static int findNextVisibleIndex(boolean[] visible, int currentIndex, int count) {
		for (int i = 2; i < count; i++) {
			int index = (currentIndex + i) % count;
			if (visible[index]) return index;
		}
		return -1;
	}
	private static void addArcToPath(GeneralPath path, int x1, int y1, int x2, int y2, double centerX, double centerY, double radius, boolean reverse) {
		double startAngle = Math.toDegrees(Math.atan2(y1 - centerY, x1 - centerX));
		double endAngle = Math.toDegrees(Math.atan2(y2 - centerY, x2 - centerX));
		double sweep = endAngle - startAngle;
		if (sweep <= -180) { sweep += 360; } else if (sweep > 180) { sweep -= 360; }
		if (reverse) sweep += sweep > 0 ? -360 : 360;
		int numSteps = (int) (Math.abs(sweep) / 10) + 1;
		for (int i = 1; i <= numSteps; i++) {
			double angle = Math.toRadians(startAngle + sweep * i / numSteps);
			path.lineTo((float) (centerX + radius * Math.cos(angle)), (float) (centerY + radius * Math.sin(angle)));
		}
	}
}

package com.fogofwar.render;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.Stroke;
import java.awt.geom.Area;
import java.awt.geom.GeneralPath;
public final class FogRender {
	private static final int SAILING_SEA_ALPHA_FLOOR = 16;
	private FogRender() {}
	public static void fill(GeneralPath path, Rectangle bounds, int padding, GeneralPath inner) {
		path.reset();
		path.moveTo(bounds.x - padding, bounds.y - padding);
		path.lineTo(bounds.x + bounds.width + padding, bounds.y - padding);
		path.lineTo(bounds.x + bounds.width + padding, bounds.y + bounds.height + padding);
		path.lineTo(bounds.x - padding, bounds.y + bounds.height + padding);
		path.closePath();
		path.append(inner, false);
	}
	public static void drawBorder(Graphics2D graphics, Shape path, Color color, StrokeCache borderStroke, int thickness) {
		Stroke oldStroke = graphics.getStroke();
		graphics.setColor(color);
		graphics.setStroke(borderStroke.get(thickness));
		graphics.draw(path);
		graphics.setStroke(oldStroke);
	}
	public static Area createDifferenceArea(Shape boundary, Shape innerBoundary) {
		Area area = new Area(boundary);
		area.subtract(new Area(innerBoundary));
		return area;
	}
	public static final class SailingSeaCache {
		private Color colour;
		private Color sailingSea;
		public Color get(Color c) {
			if (!c.equals(colour)) {
				sailingSea = new Color(c.getRed(), c.getGreen(), c.getBlue(), Math.max(SAILING_SEA_ALPHA_FLOOR, c.getAlpha() / 4));
				colour = c;
			}
			return sailingSea;
		}
	}
	public static final class StrokeCache {
		private BasicStroke stroke;
		private int width = -1;
		public BasicStroke get(int w) {
			if (stroke == null || width != w) {
				stroke = new BasicStroke(w);
				width = w;
			}
			return stroke;
		}
	}
}

package com.fogofwar.render;
import com.fogofwar.coord.WorldEntityCoords;
import lombok.Getter;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
public final class RenderCenter {
	@Getter
	private final WorldView worldView;
	@Getter
	private final WorldPoint worldPoint;
	private final LocalPoint center;
	private LocalPoint snappedCenter;
	private WorldPoint snappedWorldPoint;
	@Getter
	private final boolean onWorldEntity;
	private RenderCenter(WorldView worldView, WorldPoint worldPoint, LocalPoint localPoint, LocalPoint targetLocalPoint, boolean onWorldEntity) {
		this.worldView = worldView;
		this.worldPoint = worldPoint;
		this.onWorldEntity = onWorldEntity;
		this.center = onWorldEntity ? targetLocalPoint : localPoint;
	}
	static RenderCenter resolve(Player p, WorldView topWv) {
		if (p == null) return null;
		WorldView pwv = p.getWorldView();
		if (topWv == null) return null;
		if (pwv == null || pwv.isTopLevel()) {
			WorldPoint wp = p.getWorldLocation();
			LocalPoint lp = p.getLocalLocation();
			if (lp == null || lp.getWorldView() != topWv.getId()) lp = wp != null ? LocalPoint.fromWorld(topWv, wp) : null;
			if (wp == null || lp == null) return null;
			return new RenderCenter(topWv, wp, lp, lp, false);
		}
		WorldEntity we = WorldEntityCoords.getPlayerWorldEntity(p, topWv);
		if (we == null) return null;
		if (!WorldEntityCoords.isShip(we)) {
			WorldEntityCoords.ResolvedPoint point = WorldEntityCoords.resolveTopLevel(p, pwv, topWv, we);
			return point != null ? new RenderCenter(topWv, point.worldPoint, point.localPoint, point.localPoint, false) : null;
		}
		LocalPoint boatLp = we.getLocalLocation();
		if (boatLp == null) return null;
		LocalPoint boatTarget = we.getTargetLocation();
		if (boatTarget == null) boatTarget = boatLp;
		WorldPoint boatWp = WorldEntityCoords.toTopLevelWorldPoint(topWv, boatLp);
		return new RenderCenter(topWv, boatWp, boatLp, boatTarget, true);
	}
	public LocalPoint snappedCenter() {
		if (snappedCenter == null) snappedCenter = snapCenter(center, worldView);
		return snappedCenter;
	}
	public WorldPoint getSnappedWorldPoint() {
		LocalPoint snapped = snappedCenter();
		if (snappedWorldPoint == null) snappedWorldPoint = WorldPoint.fromLocal(worldView, snapped.getX(), snapped.getY(), worldPoint.getPlane());
		return snappedWorldPoint;
	}
	private static LocalPoint snapCenter(LocalPoint lp, WorldView worldView) {
		return new LocalPoint(snapAxis(lp.getX()), snapAxis(lp.getY()), worldView);
	}
	private static int snapAxis(int current) { return (current / Perspective.LOCAL_TILE_SIZE) * Perspective.LOCAL_TILE_SIZE + Perspective.LOCAL_HALF_TILE_SIZE; }
}

package com.fogofwar.render;
import com.fogofwar.lifecycle.LifecycleComponent;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.WorldViewLoaded;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import javax.inject.Inject;
import javax.inject.Singleton;
@Singleton
public class RenderCenterProvider extends LifecycleComponent {
	private final Client client;
	private RenderCenter current;
	private boolean resolved;
	private WorldView topWorldView;
	@Inject
	public RenderCenterProvider(Client client, EventBus eventBus) {
		super(eventBus);
		this.client = client;
	}
	public RenderCenter get(Player player) {
		if (!resolved) {
			current = RenderCenter.resolve(player, getTopLevelWorldView(player));
			resolved = true;
		}
		return current;
	}
	public WorldView getTopLevelWorldView(Player player) {
		WorldView worldView = player != null ? player.getWorldView() : null;
		if (worldView != null && worldView.isTopLevel()) topWorldView = worldView;
		else if (topWorldView == null) topWorldView = client.getTopLevelWorldView();
		return topWorldView;
	}
	private void clear() {
		if (!resolved) return;
		current = null;
		resolved = false;
	}
	private void clearAll() {
		clear();
		topWorldView = null;
	}
	@Override
	protected void onStop() { clearAll(); }
	@Subscribe
	@SuppressWarnings("unused")
	public void onBeforeRender(BeforeRender event) { clear(); }
	@Subscribe
	@SuppressWarnings("unused")
	public void onWorldViewLoaded(WorldViewLoaded event) {
		if (!event.getWorldView().isTopLevel()) return;
		topWorldView = event.getWorldView();
		clear();
	}
}

package com.fogofwar.render.minimap;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.geom.Area;
import java.awt.geom.Ellipse2D;
import javax.inject.Inject;
import javax.inject.Singleton;
@Singleton
public final class MinimapClipProvider {
	private static final int RESIZED_MINIMAP_CLIP_PADDING = 1;
	private static final int FIXED_MINIMAP_CLIP_PADDING = 3;
	private static final int[] ORB_WIDGETS = {InterfaceID.Orbs.HEALTH_BACKING, InterfaceID.Orbs.PRAYER_BACKING, InterfaceID.Orbs.RUNENERGY_BACKING, InterfaceID.Orbs.SPECENERGY_BACKING, InterfaceID.Orbs.ORB_WORLDMAP};
	private final Client client;
	private Rectangle[] currentOrbBounds;
	private Rectangle cachedMinimapBounds;
	private Shape cachedClipShape;
	private long cachedOrbsHash;
	private boolean cachedResized;
	private Widget probeWidget;
	private Rectangle probeBounds;
	private long probeOrbsHash;
	private int probeCycle = Integer.MIN_VALUE;
	private boolean probeResized;
	@Inject
	public MinimapClipProvider(Client client) { this.client = client; }
	public Widget getMinimapWidget() {
		if (client.isResized()) {
			if (client.getVarbitValue(VarbitID.RESIZABLE_STONE_ARRANGEMENT) == 1) return client.getWidget(InterfaceID.ToplevelPreEoc.MINIMAP);
			return client.getWidget(InterfaceID.ToplevelOsrsStretch.MINIMAP);
		}
		return client.getWidget(InterfaceID.Toplevel.MINIMAP);
	}
	public void clearCaches() {
		cachedMinimapBounds = null;
		cachedClipShape = null;
		cachedOrbsHash = 0;
		probeWidget = null;
		probeBounds = null;
		probeOrbsHash = 0;
		probeCycle = Integer.MIN_VALUE;
		currentOrbBounds = null;
	}
	public Shape getClipShape(Widget minimapWidget) {
		probe(minimapWidget);
		Rectangle bounds = probeBounds;
		boolean resized = probeResized;
		long orbsHash = probeOrbsHash;
		if (cachedClipShape != null && bounds.equals(cachedMinimapBounds) && orbsHash == cachedOrbsHash && resized == cachedResized) return cachedClipShape;
		Area clipArea = createEllipse(bounds, resized ? RESIZED_MINIMAP_CLIP_PADDING : FIXED_MINIMAP_CLIP_PADDING);
		for (Rectangle ob : currentOrbBounds) {
			if (ob == null) continue;
			clipArea.subtract(createEllipse(ob, 0));
		}
		cachedClipShape = clipArea;
		cachedMinimapBounds = new Rectangle(bounds);
		cachedOrbsHash = orbsHash;
		cachedResized = resized;
		return cachedClipShape;
	}
	Rectangle getMinimapBounds(Widget minimapWidget) {
		probe(minimapWidget);
		return probeBounds;
	}
	private void probe(Widget minimapWidget) {
		int cycle = client.getGameCycle();
		if (probeWidget == minimapWidget && probeCycle == cycle) return;
		probeWidget = minimapWidget;
		probeBounds = minimapWidget.getBounds();
		probeResized = client.isResized();
		probeOrbsHash = collectOrbBoundsAndHash();
		probeCycle = cycle;
	}
	private static Area createEllipse(Rectangle bounds, int padding) { return new Area(new Ellipse2D.Double(bounds.getX() - padding, bounds.getY() - padding, bounds.getWidth() + padding * 2, bounds.getHeight() + padding * 2)); }
	private long collectOrbBoundsAndHash() {
		if (currentOrbBounds == null) currentOrbBounds = new Rectangle[ORB_WIDGETS.length];
		long h = 1469598103934665603L;
		for (int i = 0; i < ORB_WIDGETS.length; i++) {
			Widget orb = client.getWidget(ORB_WIDGETS[i]);
			Rectangle b = (orb != null && !orb.isHidden()) ? orb.getBounds() : null;
			currentOrbBounds[i] = b;
			if (b == null) h ^= 0xDEADBEEFL;
			else h ^= ((b.x & 0xFFFFL) << 48) ^ ((b.y & 0xFFFFL) << 32) ^ ((b.width & 0xFFFFL) << 16) ^ (b.height & 0xFFFFL);
			h *= 1099511628211L;
		}
		return h;
	}
}

package com.fogofwar.render.minimap;
import com.fogofwar.render.FogRender;
import com.fogofwar.render.FogRender.SailingSeaCache;
import com.fogofwar.render.FogRender.StrokeCache;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.geom.Area;
import java.awt.geom.GeneralPath;
import java.awt.geom.Rectangle2D;
final class MinimapFogMask {
	private GeneralPath fogFillPath;
	private StrokeCache borderStroke;
	private SailingSeaCache sailingSeaFog;
	private SailingSeaCache sailingSeaBorder;
	void renderFog(Graphics2D graphics, Shape minimapClipShape, GeneralPath path, Color colour) {
		Rectangle2D bounds = minimapClipShape.getBounds2D();
		if (path.contains(bounds)) return;
		Rectangle b = bounds.getBounds();
		if (fogFillPath == null) fogFillPath = new GeneralPath(GeneralPath.WIND_EVEN_ODD);
		FogRender.fill(fogFillPath, b, 1, path);
		graphics.setColor(colour);
		graphics.fill(fogFillPath);
	}
	void renderFullFog(Graphics2D graphics, Shape minimapClipShape, Color colour) {
		graphics.setColor(colour);
		graphics.fill(minimapClipShape);
	}
	void renderBorder(Graphics2D graphics, Shape minimapClipShape, GeneralPath path, Color colour, int thickness) {
		if (path.contains(minimapClipShape.getBounds2D())) return;
		if (borderStroke == null) borderStroke = new StrokeCache();
		FogRender.drawBorder(graphics, path, colour, borderStroke, thickness);
	}
	void renderSailingSeaFog(Graphics2D graphics, GeneralPath boundary, GeneralPath innerBoundary, Color colour) {
		Area area = FogRender.createDifferenceArea(boundary, innerBoundary);
		if (area.isEmpty()) return;
		if (sailingSeaFog == null) sailingSeaFog = new SailingSeaCache();
		graphics.setColor(sailingSeaFog.get(colour));
		graphics.fill(area);
	}
	void renderSailingSeaBorder(Graphics2D graphics, Shape minimapClipShape, GeneralPath path, Color colour, int thickness) {
		if (path.contains(minimapClipShape.getBounds2D())) return;
		if (borderStroke == null) borderStroke = new StrokeCache();
		if (sailingSeaBorder == null) sailingSeaBorder = new SailingSeaCache();
		FogRender.drawBorder(graphics, path, sailingSeaBorder.get(colour), borderStroke, thickness);
	}
}

package com.fogofwar.render.minimap;
import com.fogofwar.config.FogDisplayMode;
import com.fogofwar.config.FogOfWarConfig;
import com.fogofwar.render.RenderCenter;
import com.fogofwar.render.RenderCenterProvider;
import com.fogofwar.state.ClientState;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import javax.inject.Inject;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.geom.GeneralPath;
public final class MinimapFogOverlay extends Overlay {
	private final FogOfWarConfig config;
	private final ClientState clientState;
	private final RenderCenterProvider renderCenterProvider;
	private final MinimapClipProvider clipProvider;
	private final Client client;
	private MinimapRenderBoundary renderBoundary;
	private MinimapFogMask fogMask;
	@Inject
	public MinimapFogOverlay(Client client, FogOfWarConfig config, ClientState clientState, RenderCenterProvider renderCenterProvider, MinimapClipProvider clipProvider) {
		this.config = config;
		this.clientState = clientState;
		this.renderCenterProvider = renderCenterProvider;
		this.clipProvider = clipProvider;
		this.client = client;
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(Overlay.PRIORITY_LOW);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}
	public void clearCaches() {
		clipProvider.clearCaches();
		renderBoundary = null;
		fogMask = null;
	}
	@Override
	public Dimension render(Graphics2D graphics) {
		Player localPlayer = clientState.getLocalPlayerIfReady();
		if (localPlayer == null) return null;
		FogDisplayMode mode = config.minimapDisplayMode();
		boolean fogMode = mode.showsFog();
		boolean borderMode = mode.showsBorder();
		if (!fogMode && !borderMode) return null;
		Color fogColour = fogMode ? config.minimapFogColour() : null;
		Color borderColour = borderMode ? config.minimapBorderColour() : null;
		boolean showFog = fogMode && fogColour.getAlpha() > 0;
		boolean showBorder = borderMode && borderColour.getAlpha() > 0;
		boolean mayShowSailingArea = config.showLandAreaWhileSailing();
		if (!showFog && !showBorder && !mayShowSailingArea) return null;
		Widget minimap = clipProvider.getMinimapWidget();
		if (minimap == null || minimap.isHidden()) return null;
		RenderCenter rc = renderCenterProvider.get(localPlayer);
		if (rc == null) return null;
		boolean showSailingArea = rc.isOnWorldEntity() && mayShowSailingArea;
		boolean showSailingFog = showSailingArea && fogMode;
		boolean showSailingBorder = showSailingArea && borderMode;
		if (!showFog && !showBorder && !showSailingFog && !showSailingBorder) return null;
		if (renderBoundary == null) renderBoundary = new MinimapRenderBoundary(client);
		if (fogMask == null) fogMask = new MinimapFogMask();
		Rectangle minimapBounds = clipProvider.getMinimapBounds(minimap);
		Shape minimapClipShape = clipProvider.getClipShape(minimap);
		Shape oldClip = graphics.getClip();
		graphics.clip(minimapClipShape);
		try {
			int landRadius = config.landRenderDistance();
			int borderThickness = showBorder || showSailingBorder ? config.minimapBorderThickness() : 0;
			if (rc.isOnWorldEntity()) renderSailingFrame(graphics, showFog, showBorder, showSailingFog, showSailingBorder, rc, minimapBounds, minimapClipShape, landRadius, fogColour, borderColour, borderThickness);
			else renderLandFrame(graphics, showFog, showBorder, rc, minimapBounds, minimapClipShape, landRadius, fogColour, borderColour, borderThickness);
			return null;
		} finally { graphics.setClip(oldClip); }
	}
	private void renderLandFrame(Graphics2D graphics, boolean showFog, boolean showBorder, RenderCenter rc, Rectangle minimapBounds, Shape minimapClipShape, int landRadius, Color fogColour, Color borderColour, int borderThickness) {
		GeneralPath landPath = renderBoundary.createLandRenderAreaPath(rc, landRadius, minimapBounds);
		if (landPath == null) {
			if (showFog) fogMask.renderFullFog(graphics, minimapClipShape, fogColour);
			return;
		}
		if (showFog) fogMask.renderFog(graphics, minimapClipShape, landPath, fogColour);
		if (showBorder) fogMask.renderBorder(graphics, minimapClipShape, landPath, borderColour, borderThickness);
	}
	private void renderSailingFrame(Graphics2D graphics, boolean showFog, boolean showBorder, boolean showSailingFog, boolean showSailingBorder, RenderCenter rc, Rectangle minimapBounds, Shape minimapClipShape, int landRadius, Color fogColour, Color borderColour, int borderThickness) {
		int seaRadius = config.sailingRenderDistance();
		GeneralPath seaPath = renderBoundary.createSeaRenderAreaPath(rc, seaRadius, minimapBounds);
		if (seaPath == null) {
			if (showFog) fogMask.renderFullFog(graphics, minimapClipShape, fogColour);
			return;
		}
		GeneralPath landPath = showSailingFog || showSailingBorder ? renderBoundary.createLandRenderAreaPath(rc, landRadius, minimapBounds) : null;
		if (showFog) fogMask.renderFog(graphics, minimapClipShape, seaPath, fogColour);
		if (showSailingFog && landPath != null) fogMask.renderSailingSeaFog(graphics, seaPath, landPath, fogColour);
		if (showBorder) fogMask.renderBorder(graphics, minimapClipShape, seaPath, borderColour, borderThickness);
		if (showSailingBorder && landPath != null) fogMask.renderSailingSeaBorder(graphics, minimapClipShape, landPath, borderColour, borderThickness);
	}
}

package com.fogofwar.render.minimap;
import com.fogofwar.render.BoundaryPathBuilder;
import com.fogofwar.render.RenderCenter;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import java.awt.Rectangle;
import java.awt.geom.GeneralPath;
final class MinimapRenderBoundary implements BoundaryPathBuilder.Strategy {
	private static final int MINIMAP_RENDER_AREA_PADDING = 1;
	private static final int MINIMAP_PROJECTION_DISTANCE = 32768;
	private final Client client;
	private int[] boundaryX;
	private int[] boundaryY;
	private boolean[] boundaryVisible;
	private int boundaryCount;
	private PathCache seaRenderAreaPath;
	private PathCache landRenderAreaPath;
	private Rectangle currentMinimapBounds;
	private Point currentCenterPoint;
	private PathCache currentCache;
	MinimapRenderBoundary(Client client) { this.client = client; }
	GeneralPath createSeaRenderAreaPath(RenderCenter rc, int radius, Rectangle minimapBounds) {
		if (seaRenderAreaPath == null) seaRenderAreaPath = new PathCache();
		return buildRenderAreaPath(rc, radius, minimapBounds, seaRenderAreaPath);
	}
	GeneralPath createLandRenderAreaPath(RenderCenter rc, int radius, Rectangle minimapBounds) {
		if (landRenderAreaPath == null) landRenderAreaPath = new PathCache();
		return buildRenderAreaPath(rc, radius, minimapBounds, landRenderAreaPath);
	}
	private GeneralPath buildRenderAreaPath(RenderCenter rc, int radius, Rectangle minimapBounds, PathCache cache) {
		LocalPoint centerLp = rc.snappedCenter();
		WorldPoint centerWp = rc.getSnappedWorldPoint();
		if (centerWp == null) return null;
		currentMinimapBounds = minimapBounds;
		currentCenterPoint = Perspective.localToMinimap(client, centerLp, MINIMAP_PROJECTION_DISTANCE);
		currentCache = cache;
		int centerPointX = currentCenterPoint != null ? currentCenterPoint.getX() : Integer.MIN_VALUE;
		int centerPointY = currentCenterPoint != null ? currentCenterPoint.getY() : Integer.MIN_VALUE;
		int yaw = client.getCameraYawTarget();
		double zoom = client.getMinimapZoom();
		if (cache.matches(rc.getWorldView(), centerWp, centerLp, radius, minimapBounds, centerPointX, centerPointY, yaw, zoom)) return cache.lastValid();
		collectBoundaryPoints(rc.getWorldView(), centerWp, centerLp, radius);
		double arcRadius = Math.max(minimapBounds.width, minimapBounds.height) / 2.0 + 1;
		GeneralPath path = BoundaryPathBuilder.build(cache.working(), boundaryX, boundaryY, boundaryVisible, boundaryCount, minimapBounds.getCenterX(), minimapBounds.getCenterY(), arcRadius, this);
		return path == cache.working() && isValid(path) ? cache.saveValid(rc.getWorldView(), centerWp, centerLp, radius, minimapBounds, centerPointX, centerPointY, yaw, zoom) : path;
	}
	@Override
	public GeneralPath coverage(GeneralPath path) { return fullMinimapCoveragePath(path); }
	@Override
	public boolean isValid(GeneralPath path) { return currentCenterPoint == null || path.contains(currentCenterPoint.getX(), currentCenterPoint.getY()); }
	@Override
	public GeneralPath fallback(GeneralPath path) { return currentCache.hasLastValid() ? currentCache.lastValid() : path; }
	private void padRenderAreaPoint(int index, int x, int y) {
		double cx = currentCenterPoint != null ? currentCenterPoint.getX() : currentMinimapBounds.getCenterX();
		double cy = currentCenterPoint != null ? currentCenterPoint.getY() : currentMinimapBounds.getCenterY();
		double dx = x - cx;
		double dy = y - cy;
		double distance = Math.hypot(dx, dy);
		if (distance == 0) {
			boundaryX[index] = x;
			boundaryY[index] = y;
			return;
		}
		boundaryX[index] = (int) Math.round(x + dx * MINIMAP_RENDER_AREA_PADDING / distance);
		boundaryY[index] = (int) Math.round(y + dy * MINIMAP_RENDER_AREA_PADDING / distance);
	}
	private void collectBoundaryPoints(WorldView worldView, WorldPoint center, LocalPoint centerLp, int radius) {
		boundaryCount = 0;
		int sampleRate = Math.max(1, radius / 12);
		ensureBoundaryCapacity(4 + 4 * (radius * 2 / sampleRate + 1));
		int halfTile = Perspective.LOCAL_HALF_TILE_SIZE;
		addMinimapPoint(worldView, center, centerLp, -radius, -radius, -halfTile, -halfTile);
		for (int x = -radius; x <= radius; x += sampleRate) addMinimapPoint(worldView, center, centerLp, x, -radius, 0, -halfTile);
		addMinimapPoint(worldView, center, centerLp, radius, -radius, halfTile, -halfTile);
		for (int y = -radius; y <= radius; y += sampleRate) addMinimapPoint(worldView, center, centerLp, radius, y, halfTile, 0);
		addMinimapPoint(worldView, center, centerLp, radius, radius, halfTile, halfTile);
		for (int x = radius; x >= -radius; x -= sampleRate) addMinimapPoint(worldView, center, centerLp, x, radius, 0, halfTile);
		addMinimapPoint(worldView, center, centerLp, -radius, radius, -halfTile, halfTile);
		for (int y = radius; y >= -radius; y -= sampleRate) addMinimapPoint(worldView, center, centerLp, -radius, y, -halfTile, 0);
	}
	private void addMinimapPoint(WorldView worldView, WorldPoint centerWp, LocalPoint centerLp, int tileXOffset, int tileYOffset, int xOffset, int yOffset) {
		int index = boundaryCount++;
		boundaryVisible[index] = false;
		if (!WorldPoint.isInScene(worldView, centerWp.getX() + tileXOffset, centerWp.getY() + tileYOffset)) return;
		int x = centerLp.getX() + tileXOffset * Perspective.LOCAL_TILE_SIZE + xOffset;
		int y = centerLp.getY() + tileYOffset * Perspective.LOCAL_TILE_SIZE + yOffset;
		Point projected = Perspective.localToMinimap(client, new LocalPoint(x, y, worldView), MINIMAP_PROJECTION_DISTANCE);
		if (projected == null) return;
		boundaryVisible[index] = true;
		padRenderAreaPoint(index, projected.getX(), projected.getY());
	}
	private void ensureBoundaryCapacity(int capacity) {
		if (boundaryX != null && boundaryX.length >= capacity) return;
		boundaryX = new int[capacity];
		boundaryY = new int[capacity];
		boundaryVisible = new boolean[capacity];
	}
	private GeneralPath fullMinimapCoveragePath(GeneralPath path) {
		Rectangle minimapBounds = currentMinimapBounds;
		path.reset();
		double centerX = minimapBounds.getCenterX();
		double centerY = minimapBounds.getCenterY();
		double radius = Math.max(minimapBounds.width, minimapBounds.height);
		int numSegments = 32;
		for (int i = 0; i < numSegments; i++) {
			double angle = 2 * Math.PI * i / numSegments;
			double x = centerX + radius * Math.cos(angle);
			double y = centerY + radius * Math.sin(angle);
			if (i == 0) path.moveTo(x, y);
			else path.lineTo(x, y);
		}
		path.closePath();
		return path;
	}
	private static final class PathCache {
		private GeneralPath working = new GeneralPath();
		private GeneralPath lastValid = new GeneralPath();
		private WorldView worldView;
		private boolean valid;
		private int worldViewId, centerWorldX, centerWorldY, centerPlane, centerLocalX, centerLocalY, radius, boundsX, boundsY, boundsW, boundsH, centerPointX, centerPointY, yaw;
		private double zoom;
		private GeneralPath working() { return working; }
		private GeneralPath lastValid() { return lastValid; }
		private boolean hasLastValid() { return lastValid.getCurrentPoint() != null; }
		private boolean matches(WorldView worldView, WorldPoint centerWp, LocalPoint centerLp, int radius, Rectangle bounds, int centerPointX, int centerPointY, int yaw, double zoom) {
			return valid
					&& this.worldView == worldView
					&& this.worldViewId == worldView.getId()
					&& centerWorldX == centerWp.getX()
					&& centerWorldY == centerWp.getY()
					&& centerPlane == centerWp.getPlane()
					&& centerLocalX == centerLp.getX()
					&& centerLocalY == centerLp.getY()
					&& this.radius == radius
					&& boundsX == bounds.x
					&& boundsY == bounds.y
					&& boundsW == bounds.width
					&& boundsH == bounds.height
					&& this.centerPointX == centerPointX
					&& this.centerPointY == centerPointY
					&& this.yaw == yaw
					&& Double.compare(this.zoom, zoom) == 0;
		}
		private GeneralPath saveValid(WorldView worldView, WorldPoint centerWp, LocalPoint centerLp, int radius, Rectangle bounds, int centerPointX, int centerPointY, int yaw, double zoom) {
			GeneralPath valid = working;
			working = lastValid;
			lastValid = valid;
			working.reset();
			this.valid = true;
			this.worldView = worldView;
			this.worldViewId = worldView.getId();
			this.centerWorldX = centerWp.getX();
			this.centerWorldY = centerWp.getY();
			this.centerPlane = centerWp.getPlane();
			this.centerLocalX = centerLp.getX();
			this.centerLocalY = centerLp.getY();
			this.radius = radius;
			this.boundsX = bounds.x;
			this.boundsY = bounds.y;
			this.boundsW = bounds.width;
			this.boundsH = bounds.height;
			this.centerPointX = centerPointX;
			this.centerPointY = centerPointY;
			this.yaw = yaw;
			this.zoom = zoom;
			return lastValid;
		}
	}
}

package com.fogofwar.render.world;
import com.fogofwar.coord.WorldEntityCoords;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.geom.Area;
import java.awt.geom.GeneralPath;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Set;
final class ActorCutoutMask {
	private static final int ACTOR_CUTOUT_BUCKET_SIZE = 48;
	private static final int PRIORITY_SCORE = Integer.MIN_VALUE / 2;
	private static final List<ActorCutoutCandidate> EMPTY_CANDIDATES = Collections.emptyList();
	private static final Comparator<ActorCutoutCandidate> ACTOR_CUTOUT_CANDIDATE_ORDER = (a, b) -> {
		int c = Integer.compare(a.score, b.score);
		if (c != 0) return c;
		c = Boolean.compare(!a.hit, !b.hit);
		if (c != 0) return c;
		c = Integer.compare(b.canvasY, a.canvasY);
		if (c != 0) return c;
		c = Integer.compare(a.canvasX, b.canvasX);
		if (c != 0) return c;
		c = Integer.compare(a.worldX, b.worldX);
		if (c != 0) return c;
		return Integer.compare(a.worldY, b.worldY);
	};
	private final Client client;
	private final VisibleActorTracker visibleActorTracker;
	private final ActorHullCache hullCache = new ActorHullCache();
	private final GeneralPath exclusionPath = new GeneralPath();
	private List<ActorCutoutCandidate> exclusionCandidates = EMPTY_CANDIDATES;
	private boolean[] usedBuckets = new boolean[0];
	private Rectangle viewport;
	private Player localPlayer;
	private int exclusionCandidateCount;
	private int lastCamX, lastCamY, lastCamZ, lastCamPitch, lastCamYaw, lastScale, lastVpX, lastVpY, lastVpW, lastVpH;
	private float lastCamFpX, lastCamFpY, lastCamFpZ, lastCamFpPitch, lastCamFpYaw;
	private boolean lastGpu;
	private boolean prepared;
	private boolean retainHullCache;
	ActorCutoutMask(Client client, VisibleActorTracker visibleActorTracker) {
		this.client = client;
		this.visibleActorTracker = visibleActorTracker;
	}
	void beginFrame(Player localPlayer) {
		this.localPlayer = localPlayer;
		prepared = false;
		retainHullCache = false;
	}
	void endFrame() {
		if (prepared && retainHullCache) hullCache.retainSeen();
		localPlayer = null;
	}
	Area createExclusionArea(Shape fog, Rectangle viewport, WorldView worldView, LocalPoint centerLp, int plane, int radius, int limit) {
		this.viewport = viewport;
		Set<Actor> visibleActors = visibleActorTracker.getVisibleActors();
		int expectedActors = Math.max(16, Math.min(256, visibleActors.size() + 1));
		prepareFrame(expectedActors);
		retainHullCache = true;
		if (exclusionCandidates == EMPTY_CANDIDATES) exclusionCandidates = new ArrayList<>(expectedActors);
		boolean all = limit == Integer.MAX_VALUE;
		try {
			collectExclusionCandidates(visibleActors, worldView, fog, centerLp, plane, radius);
			if (exclusionCandidateCount == 0) return null;
			exclusionPath.reset();
			int selected;
			if (all || exclusionCandidateCount <= limit) selected = appendAllExclusionHulls(fog);
			else {
				int bucketColumns = Math.max(1, (viewport.width + ACTOR_CUTOUT_BUCKET_SIZE - 1) / ACTOR_CUTOUT_BUCKET_SIZE);
				rankExclusionCandidates(centerLp, radius * Perspective.LOCAL_TILE_SIZE + Perspective.LOCAL_HALF_TILE_SIZE, bucketColumns);
				exclusionCandidates.subList(0, exclusionCandidateCount).sort(ACTOR_CUTOUT_CANDIDATE_ORDER);
				selected = appendSelectedExclusionHulls(fog, limit, bucketColumns);
			}
			return selected > 0 ? new Area(exclusionPath) : null;
		} finally {
			clearExclusionCandidates();
		}
	}
	private void prepareFrame(int expectedActors) {
		if (prepared) return;
		updateCameraState();
		hullCache.beginFrame(expectedActors);
		prepared = true;
	}
	private void updateCameraState() {
		lastGpu = client.isGpu();
		lastCamX = client.getCameraX();
		lastCamY = client.getCameraY();
		lastCamZ = client.getCameraZ();
		lastCamPitch = client.getCameraPitch();
		lastCamYaw = client.getCameraYaw();
		lastCamFpX = client.getCameraFpX();
		lastCamFpY = client.getCameraFpY();
		lastCamFpZ = client.getCameraFpZ();
		lastCamFpPitch = client.getCameraFpPitch();
		lastCamFpYaw = client.getCameraFpYaw();
		lastScale = client.getScale();
		lastVpX = viewport.x;
		lastVpY = viewport.y;
		lastVpW = viewport.width;
		lastVpH = viewport.height;
	}
	private int appendAllExclusionHulls(Shape fog) {
		int selected = 0;
		for (int i = 0; i < exclusionCandidateCount; i++) {
			Shape hull = getCandidateHull(exclusionCandidates.get(i), fog);
			if (hull == null) continue;
			exclusionPath.append(hull, false);
			selected++;
		}
		return selected;
	}
	private boolean isOutsideFog(Shape fog, Rectangle bounds) {
		int minX = Math.max(bounds.x, viewport.x), minY = Math.max(bounds.y, viewport.y);
		return !fog.intersects(minX, minY, Math.min(bounds.x + bounds.width, viewport.x + viewport.width) - minX, Math.min(bounds.y + bounds.height, viewport.y + viewport.height) - minY);
	}
	private void collectExclusionCandidates(Set<Actor> visibleActors, WorldView worldView, Shape fog, LocalPoint centerLp, int plane, int radius) {
		exclusionCandidateCount = 0;
		int localRadius = radius * Perspective.LOCAL_TILE_SIZE + Perspective.LOCAL_HALF_TILE_SIZE;
		if (localPlayer != null) collectExclusionCandidate(localPlayer, worldView, fog, centerLp, plane, localRadius);
		for (Actor actor : visibleActors) {
			if (actor == localPlayer) continue;
			collectExclusionCandidate(actor, worldView, fog, centerLp, plane, localRadius);
		}
	}
	private void collectExclusionCandidate(Actor actor, WorldView worldView, Shape fog, LocalPoint centerLp, int plane, int localRadius) {
		if (actor == null) return;
		boolean priority = actor == localPlayer;
		WorldView actorWv = actor.getWorldView();
		if (actorWv == null) return;
		WorldPoint actorWorldPoint = actor.getWorldLocation();
		LocalPoint lp = actor.getLocalLocation();
		int worldX, worldY, worldPlane;
		if (actorWv.isTopLevel()) {
			if (actorWorldPoint == null) return;
			if (lp == null) lp = LocalPoint.fromWorld(worldView, actorWorldPoint);
			if (lp == null) return;
			worldX = actorWorldPoint.getX();
			worldY = actorWorldPoint.getY();
			worldPlane = actorWorldPoint.getPlane();
		} else {
			WorldEntity worldEntity = WorldEntityCoords.getWorldEntity(actorWv, worldView);
			if (worldEntity == null) return;
			if (lp == null && actorWorldPoint != null) lp = LocalPoint.fromWorld(actorWv, actorWorldPoint);
			if (lp == null) return;
			lp = worldEntity.transformToMainWorld(lp);
			if (lp == null) return;
			worldX = (lp.getX() >> Perspective.LOCAL_COORD_BITS) + worldView.getBaseX();
			worldY = (lp.getY() >> Perspective.LOCAL_COORD_BITS) + worldView.getBaseY();
			worldPlane = worldView.getPlane();
		}
		if (worldPlane != plane) return;
		boolean onSubWorld = !actorWv.isTopLevel();
		ActorHullCache.Entry cached = hullCache.get(actor);
		hullCache.markSeen(actor);
		int anim = actor.getAnimation(), frame = actor.getAnimationFrame();
		int pose = actor.getPoseAnimation(), poseFrame = actor.getPoseAnimationFrame();
		int orientation = actor.getCurrentOrientation();
		boolean hit = cached != null
				&& cached.wx == worldX && cached.wy == worldY && cached.plane == worldPlane
				&& cached.localX == lp.getX() && cached.localY == lp.getY()
				&& cached.anim == anim && cached.frame == frame
				&& cached.pose == pose && cached.poseFrame == poseFrame
				&& cached.orientation == orientation
				&& cached.gpu == lastGpu
				&& cached.camX == lastCamX && cached.camY == lastCamY && cached.camZ == lastCamZ && cached.camPitch == lastCamPitch && cached.camYaw == lastCamYaw
				&& Float.compare(cached.camFpX, lastCamFpX) == 0 && Float.compare(cached.camFpY, lastCamFpY) == 0 && Float.compare(cached.camFpZ, lastCamFpZ) == 0 && Float.compare(cached.camFpPitch, lastCamFpPitch) == 0 && Float.compare(cached.camFpYaw, lastCamFpYaw) == 0
				&& cached.scale == lastScale
				&& cached.vpX == lastVpX && cached.vpY == lastVpY && cached.vpW == lastVpW && cached.vpH == lastVpH;
		if (hit && isOutsideFog(fog, cached.bounds)) return;
		int localX, localY, canvasX, canvasY, edgeDistance;
		if (hit) {
			localX = cached.localX;
			localY = cached.localY;
			canvasX = cached.canvasX;
			canvasY = cached.canvasY;
		} else {
			localX = lp.getX();
			localY = lp.getY();
			edgeDistance = getEdgeDistance(localX, localY, centerLp, localRadius);
			int footprintRadius = Math.max(Perspective.LOCAL_TILE_SIZE, actor.getFootprintSize() * Perspective.LOCAL_TILE_SIZE / 2);
			if (!priority && !onSubWorld && edgeDistance < -footprintRadius) return;
			Point canvasPoint = Perspective.localToCanvas(client, lp, plane);
			if (!priority && (canvasPoint == null || !viewport.contains(canvasPoint.getX(), canvasPoint.getY()))) return;
			canvasX = canvasPoint != null ? canvasPoint.getX() : viewport.x + viewport.width / 2;
			canvasY = canvasPoint != null ? canvasPoint.getY() : viewport.y + viewport.height / 2;
		}
		addExclusionCandidate(actor, cached, worldX, worldY, worldPlane, anim, frame, pose, poseFrame, orientation, hit, canvasX, canvasY, localX, localY);
	}
	private void rankExclusionCandidates(LocalPoint centerLp, int localRadius, int bucketColumns) {
		for (int i = 0; i < exclusionCandidateCount; i++) {
			ActorCutoutCandidate candidate = exclusionCandidates.get(i);
			if (viewport.contains(candidate.canvasX, candidate.canvasY)) candidate.bucket = getExclusionBucket(candidate.canvasX, candidate.canvasY, bucketColumns);
			candidate.score = getCandidateScore(candidate.actor, candidate.hit, getEdgeDistance(candidate.localX, candidate.localY, centerLp, localRadius));
		}
	}
	private int getEdgeDistance(int localX, int localY, LocalPoint centerLp, int localRadius) {
		int dx = Math.abs(localX - centerLp.getX());
		int dy = Math.abs(localY - centerLp.getY());
		return Math.max(dx, dy) - localRadius;
	}
	private int getCandidateScore(Actor actor, boolean hit, int edgeDistance) {
		if (actor == localPlayer) return PRIORITY_SCORE;
		int score = Math.abs(edgeDistance);
		if (edgeDistance < 0) score += Perspective.LOCAL_TILE_SIZE;
		if (!(actor instanceof Player)) score += Perspective.LOCAL_TILE_SIZE / 2;
		if (hit) score -= Perspective.LOCAL_TILE_SIZE * 8;
		return score;
	}
	private int getExclusionBucket(int canvasX, int canvasY, int bucketColumns) {
		int x = (canvasX - viewport.x) / ACTOR_CUTOUT_BUCKET_SIZE;
		int y = (canvasY - viewport.y) / ACTOR_CUTOUT_BUCKET_SIZE;
		return y * bucketColumns + x;
	}
	private void addExclusionCandidate(Actor actor, ActorHullCache.Entry cached, int worldX, int worldY, int plane, int anim, int frame, int pose, int poseFrame, int orientation, boolean hit, int canvasX, int canvasY, int localX, int localY) {
		if (exclusionCandidateCount == exclusionCandidates.size()) exclusionCandidates.add(new ActorCutoutCandidate());
		exclusionCandidates.get(exclusionCandidateCount++).set(actor, cached, worldX, worldY, plane, anim, frame, pose, poseFrame, orientation, hit, canvasX, canvasY, localX, localY);
	}
	private int appendSelectedExclusionHulls(Shape fog, int limit, int bucketColumns) {
		int bucketRows = Math.max(1, (viewport.height + ACTOR_CUTOUT_BUCKET_SIZE - 1) / ACTOR_CUTOUT_BUCKET_SIZE);
		int bucketCount = bucketColumns * bucketRows;
		if (usedBuckets.length < bucketCount) usedBuckets = new boolean[bucketCount];
		else Arrays.fill(usedBuckets, 0, bucketCount, false);
		int selected = appendPriorityExclusionHull(fog, limit);
		for (int pass = 0; pass < 2 && selected < limit; pass++) {
			for (int i = 0; i < exclusionCandidateCount && selected < limit; i++) {
				ActorCutoutCandidate candidate = exclusionCandidates.get(i);
				if (candidate.resolved) continue;
				if (pass == 0 && candidate.bucket < 0) continue;
				if (pass == 0 && usedBuckets[candidate.bucket]) continue;
				candidate.resolved = true;
				Shape hull = getCandidateHull(candidate, fog);
				if (hull == null) continue;
				if (candidate.bucket >= 0) usedBuckets[candidate.bucket] = true;
				exclusionPath.append(hull, false);
				selected++;
			}
		}
		return selected;
	}
	private int appendPriorityExclusionHull(Shape fog, int limit) {
		int selected = 0;
		for (int i = 0; i < exclusionCandidateCount && selected < limit; i++) {
			ActorCutoutCandidate candidate = exclusionCandidates.get(i);
			if (candidate.actor != localPlayer) continue;
			candidate.resolved = true;
			Shape hull = getCandidateHull(candidate, fog);
			if (hull != null) {
				exclusionPath.append(hull, false);
				selected++;
			}
			break;
		}
		return selected;
	}
	private void clearExclusionCandidates() {
		for (int i = 0; i < exclusionCandidateCount; i++) exclusionCandidates.get(i).clear();
		exclusionCandidateCount = 0;
	}
	private Shape getCandidateHull(ActorCutoutCandidate candidate, Shape fog) {
		if (candidate.hit) return candidate.cached.hull;
		Shape hull = candidate.actor.getConvexHull();
		if (hull == null) {
			hullCache.remove(candidate.actor);
			return null;
		}
		Rectangle bounds = hull.getBounds();
		cache(candidate, hull, bounds);
		return isOutsideFog(fog, bounds) ? null : hull;
	}
	private void cache(ActorCutoutCandidate candidate, Shape hull, Rectangle bounds) {
		ActorHullCache.Entry cached = hullCache.getOrCreate(candidate.actor);
		candidate.cached = cached;
		cached.hull = hull;
		cached.bounds = bounds;
		cached.wx = candidate.worldX;
		cached.wy = candidate.worldY;
		cached.plane = candidate.plane;
		cached.localX = candidate.localX;
		cached.localY = candidate.localY;
		cached.canvasX = candidate.canvasX;
		cached.canvasY = candidate.canvasY;
		cached.anim = candidate.anim;
		cached.frame = candidate.frame;
		cached.pose = candidate.pose;
		cached.poseFrame = candidate.poseFrame;
		cached.orientation = candidate.orientation;
		cached.camX = lastCamX;
		cached.camY = lastCamY;
		cached.camZ = lastCamZ;
		cached.camPitch = lastCamPitch;
		cached.camYaw = lastCamYaw;
		cached.camFpX = lastCamFpX;
		cached.camFpY = lastCamFpY;
		cached.camFpZ = lastCamFpZ;
		cached.camFpPitch = lastCamFpPitch;
		cached.camFpYaw = lastCamFpYaw;
		cached.gpu = lastGpu;
		cached.scale = lastScale;
		cached.vpX = lastVpX;
		cached.vpY = lastVpY;
		cached.vpW = lastVpW;
		cached.vpH = lastVpH;
	}
	private static final class ActorCutoutCandidate {
		private Actor actor;
		private ActorHullCache.Entry cached;
		private int worldX, worldY, plane, anim, frame, pose, poseFrame, orientation, score, bucket, canvasX, canvasY, localX, localY;
		private boolean hit, resolved;
		private void set(Actor actor, ActorHullCache.Entry cached, int worldX, int worldY, int plane, int anim, int frame, int pose, int poseFrame, int orientation, boolean hit, int canvasX, int canvasY, int localX, int localY) {
			this.actor = actor;
			this.cached = cached;
			this.worldX = worldX;
			this.worldY = worldY;
			this.plane = plane;
			this.anim = anim;
			this.frame = frame;
			this.pose = pose;
			this.poseFrame = poseFrame;
			this.orientation = orientation;
			this.hit = hit;
			this.score = 0;
			this.bucket = -1;
			this.canvasX = canvasX;
			this.canvasY = canvasY;
			this.localX = localX;
			this.localY = localY;
			this.resolved = false;
		}
		private void clear() {
			actor = null;
			cached = null;
			worldX = worldY = plane = anim = frame = pose = poseFrame = orientation = score = bucket = canvasX = canvasY = localX = localY = 0;
			hit = resolved = false;
		}
	}
}

package com.fogofwar.render.world;
import net.runelite.api.Actor;
import java.awt.Rectangle;
import java.awt.Shape;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.Map;
import java.util.Set;
final class ActorHullCache {
	private static final Set<Actor> EMPTY = Collections.emptySet();
	private static final Map<Actor, Entry> EMPTY_ENTRIES = Collections.emptyMap();
	private Map<Actor, Entry> entries = EMPTY_ENTRIES;
	private Set<Actor> seen = EMPTY;
	private int expectedActors;
	void beginFrame(int expectedActors) {
		this.expectedActors = expectedActors;
		if (seen == EMPTY) seen = Collections.newSetFromMap(new IdentityHashMap<>(expectedActors));
		else seen.clear();
	}
	void markSeen(Actor actor) { seen.add(actor); }
	Entry get(Actor actor) { return entries.get(actor); }
	Entry getOrCreate(Actor actor) {
		if (entries == EMPTY_ENTRIES) entries = new IdentityHashMap<>(expectedActors);
		return entries.computeIfAbsent(actor, a -> new Entry());
	}
	void remove(Actor actor) { if (entries != EMPTY_ENTRIES) entries.remove(actor); }
	void retainSeen() { if (entries != EMPTY_ENTRIES) entries.keySet().retainAll(seen); }
	static final class Entry {
		Shape hull;
		Rectangle bounds;
		int wx, wy, plane, anim, frame, pose, poseFrame, orientation;
		int localX, localY, canvasX, canvasY;
		int camX, camY, camZ, camPitch, camYaw, scale, vpX, vpY, vpW, vpH;
		float camFpX, camFpY, camFpZ, camFpPitch, camFpYaw;
		boolean gpu;
	}
}

package com.fogofwar.render.world;
import com.fogofwar.lifecycle.LifecycleComponent;
import lombok.Getter;
import net.runelite.api.Actor;
import net.runelite.api.Renderable;
import net.runelite.api.events.BeforeRender;
import net.runelite.client.callback.RenderCallback;
import net.runelite.client.callback.RenderCallbackManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.Set;
@Singleton
public class VisibleActorTracker extends LifecycleComponent implements RenderCallback {
	private final RenderCallbackManager renderCallbackManager;
	@Getter
	private Set<Actor> visibleActors = Collections.emptySet();
	@Inject
	public VisibleActorTracker(EventBus eventBus, RenderCallbackManager renderCallbackManager) {
		super(eventBus);
		this.renderCallbackManager = renderCallbackManager;
	}
	@Override
	protected void onStart() {
		visibleActors = Collections.newSetFromMap(new IdentityHashMap<>(256));
		renderCallbackManager.register(this);
	}
	@Override
	protected void onStop() {
		renderCallbackManager.unregister(this);
		visibleActors = Collections.emptySet();
	}
	@Subscribe
	@SuppressWarnings("unused")
	public void onBeforeRender(BeforeRender event) { visibleActors.clear(); }
	@Override
	public boolean addEntity(Renderable renderable, boolean ui) {
		if (!ui && renderable instanceof Actor) visibleActors.add((Actor) renderable);
		return true;
	}
}

package com.fogofwar.render.world;
import com.fogofwar.config.ActorCutoutLimit;
import com.fogofwar.render.FogRender;
import com.fogofwar.render.FogRender.SailingSeaCache;
import com.fogofwar.render.FogRender.StrokeCache;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.geom.Area;
import java.awt.geom.GeneralPath;
final class WorldFogMask {
	private GeneralPath fogPath;
	private StrokeCache borderStroke;
	private SailingSeaCache sailingSeaFog;
	private SailingSeaCache sailingSeaBorder;
	void renderFog(Graphics2D graphics, Rectangle viewport, WorldView worldView, GeneralPath boundary, LocalPoint centerLp, int plane, int radius, Color colour, ActorCutoutLimit cutoutLimit, ActorCutoutMask actorCutouts) {
		if (boundary.contains(viewport)) return;
		if (fogPath == null) fogPath = new GeneralPath(GeneralPath.WIND_EVEN_ODD);
		FogRender.fill(fogPath, viewport, 0, boundary);
		graphics.setColor(colour);
		Area exclusions = cutoutLimit.isEnabled() ? actorCutouts.createExclusionArea(fogPath, viewport, worldView, centerLp, plane, radius, cutoutLimit.getLimit()) : null;
		if (exclusions == null) {
			graphics.fill(fogPath);
			return;
		}
		Area fogArea = new Area(fogPath);
		fogArea.subtract(exclusions);
		graphics.fill(fogArea);
	}
	void renderFullFog(Graphics2D graphics, Rectangle viewport, Color colour) {
		graphics.setColor(colour);
		graphics.fill(viewport);
	}
	void renderBorder(Graphics2D graphics, GeneralPath boundary, Color colour, int thickness) {
		if (borderStroke == null) borderStroke = new StrokeCache();
		FogRender.drawBorder(graphics, boundary, colour, borderStroke, thickness);
	}
	void renderSailingSeaFog(Graphics2D graphics, Rectangle viewport, WorldView worldView, GeneralPath boundary, GeneralPath innerBoundary, LocalPoint centerLp, int plane, int radius, Color colour, ActorCutoutLimit cutoutLimit, ActorCutoutMask actorCutouts) {
		Area area = FogRender.createDifferenceArea(boundary, innerBoundary);
		if (area.isEmpty()) return;
		Area exclusions = cutoutLimit.isEnabled() ? actorCutouts.createExclusionArea(area, viewport, worldView, centerLp, plane, radius, cutoutLimit.getLimit()) : null;
		if (exclusions != null) {
			area.subtract(exclusions);
			if (area.isEmpty()) return;
		}
		if (sailingSeaFog == null) sailingSeaFog = new SailingSeaCache();
		graphics.setColor(sailingSeaFog.get(colour));
		graphics.fill(area);
	}
	void renderSailingSeaBorder(Graphics2D graphics, GeneralPath boundary, Color colour, int thickness) {
		if (borderStroke == null) borderStroke = new StrokeCache();
		if (sailingSeaBorder == null) sailingSeaBorder = new SailingSeaCache();
		FogRender.drawBorder(graphics, boundary, sailingSeaBorder.get(colour), borderStroke, thickness);
	}
}

package com.fogofwar.render.world;
import com.fogofwar.config.ActorCutoutLimit;
import com.fogofwar.config.FogDisplayMode;
import com.fogofwar.config.FogOfWarConfig;
import com.fogofwar.render.RenderCenter;
import com.fogofwar.render.RenderCenterProvider;
import com.fogofwar.state.ClientState;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import javax.inject.Inject;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.geom.GeneralPath;
public final class WorldFogOverlay extends Overlay {
	private final Client client;
	private final FogOfWarConfig config;
	private final ClientState clientState;
	private final RenderCenterProvider renderCenterProvider;
	private final VisibleActorTracker visibleActorTracker;
	private final Rectangle viewport = new Rectangle();
	private WorldRenderBoundary renderBoundary;
	private WorldFogMask fogMask;
	private ActorCutoutMask actorCutouts;
	@Inject
	public WorldFogOverlay(Client client, FogOfWarConfig config, ClientState clientState, RenderCenterProvider renderCenterProvider, VisibleActorTracker visibleActorTracker) {
		this.client = client;
		this.config = config;
		this.clientState = clientState;
		this.renderCenterProvider = renderCenterProvider;
		this.visibleActorTracker = visibleActorTracker;
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(Overlay.PRIORITY_LOW);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}
	public void clearCaches() {
		renderBoundary = null;
		fogMask = null;
		actorCutouts = null;
	}
	public void clearActorCaches() { actorCutouts = null; }
	@Override
	public Dimension render(Graphics2D graphics) {
		Player localPlayer = clientState.getLocalPlayerIfReady();
		if (localPlayer == null) return null;
		FogDisplayMode mode = config.worldDisplayMode();
		boolean fogMode = mode.showsFog();
		boolean borderMode = mode.showsBorder();
		if (!fogMode && !borderMode) return null;
		Color fogColour = fogMode ? config.worldFogColour() : null;
		Color borderColour = borderMode ? config.worldBorderColour() : null;
		boolean showFog = fogMode && fogColour.getAlpha() > 0;
		boolean showBorder = borderMode && borderColour.getAlpha() > 0;
		boolean mayShowSailingArea = config.showLandAreaWhileSailing();
		if (!showFog && !showBorder && !mayShowSailingArea) return null;
		setViewportBounds();
		if (viewport.isEmpty()) return null;
		RenderCenter rc = renderCenterProvider.get(localPlayer);
		if (rc == null) return null;
		boolean showSailingArea = rc.isOnWorldEntity() && mayShowSailingArea;
		boolean showSailingFog = showSailingArea && fogMode;
		boolean showSailingBorder = showSailingArea && borderMode;
		if (!showFog && !showBorder && !showSailingFog && !showSailingBorder) return null;
		if (renderBoundary == null) renderBoundary = new WorldRenderBoundary(client);
		if (fogMask == null) fogMask = new WorldFogMask();
		ActorCutoutLimit cutoutLimit = showFog || showSailingFog ? config.actorCutoutLimit() : ActorCutoutLimit.NONE;
		boolean useCutouts = cutoutLimit.isEnabled();
		if (useCutouts) {
			if (actorCutouts == null) actorCutouts = new ActorCutoutMask(client, visibleActorTracker);
			actorCutouts.beginFrame(localPlayer);
		} else clearActorCaches();
		try {
			int borderThickness = showBorder || showSailingBorder ? config.worldBorderThickness() : 0;
			renderFrame(graphics, showFog, showBorder, showSailingFog, showSailingBorder, rc, fogColour, borderColour, borderThickness, cutoutLimit);
		} finally {
			if (useCutouts) actorCutouts.endFrame();
		}
		return null;
	}
	private void renderFrame(Graphics2D graphics, boolean showFog, boolean showBorder, boolean showSailingFog, boolean showSailingBorder, RenderCenter rc, Color fogColour, Color borderColour, int borderThickness, ActorCutoutLimit cutoutLimit) {
		WorldView worldView = rc.getWorldView();
		int landRadius = config.landRenderDistance();
		boolean sailing = rc.isOnWorldEntity();
		int plane = rc.getWorldPoint().getPlane();
		if (sailing) renderSailingFrame(graphics, showFog, showBorder, showSailingFog, showSailingBorder, rc, worldView, plane, landRadius, fogColour, borderColour, borderThickness, cutoutLimit);
		else renderLandFrame(graphics, showFog, showBorder, rc, worldView, plane, landRadius, fogColour, borderColour, borderThickness, cutoutLimit);
	}
	private void renderLandFrame(Graphics2D graphics, boolean showFog, boolean showBorder, RenderCenter rc, WorldView worldView, int plane, int landRadius, Color fogColour, Color borderColour, int borderThickness, ActorCutoutLimit cutoutLimit) {
		LocalPoint landCenter = rc.snappedCenter();
		GeneralPath landBoundary = renderBoundary.createLandRenderAreaBoundary(rc, landRadius, viewport);
		if (landBoundary == null) {
			if (showFog) fogMask.renderFullFog(graphics, viewport, fogColour);
			return;
		}
		if (showFog) fogMask.renderFog(graphics, viewport, worldView, landBoundary, landCenter, plane, landRadius, fogColour, cutoutLimit, actorCutouts);
		if (showBorder) fogMask.renderBorder(graphics, landBoundary, borderColour, borderThickness);
	}
	private void renderSailingFrame(Graphics2D graphics, boolean showFog, boolean showBorder, boolean showSailingFog, boolean showSailingBorder, RenderCenter rc, WorldView worldView, int plane, int landRadius, Color fogColour, Color borderColour, int borderThickness, ActorCutoutLimit cutoutLimit) {
		int seaRadius = config.sailingRenderDistance();
		LocalPoint center = rc.snappedCenter();
		GeneralPath seaBoundary = renderBoundary.createSeaRenderAreaBoundary(rc, seaRadius, viewport);
		if (seaBoundary == null) {
			if (showFog) fogMask.renderFullFog(graphics, viewport, fogColour);
			return;
		}
		GeneralPath landBoundary = showSailingFog || showSailingBorder ? renderBoundary.createLandRenderAreaBoundary(rc, landRadius, viewport) : null;
		if (showFog) fogMask.renderFog(graphics, viewport, worldView, seaBoundary, center, plane, seaRadius, fogColour, cutoutLimit, actorCutouts);
		if (showSailingFog && landBoundary != null) fogMask.renderSailingSeaFog(graphics, viewport, worldView, seaBoundary, landBoundary, center, plane, landRadius, fogColour, cutoutLimit, actorCutouts);
		if (showBorder) fogMask.renderBorder(graphics, seaBoundary, borderColour, borderThickness);
		if (showSailingBorder && landBoundary != null) fogMask.renderSailingSeaBorder(graphics, landBoundary, borderColour, borderThickness);
	}
	private void setViewportBounds() {
		viewport.setBounds(client.getViewportXOffset(), client.getViewportYOffset(), client.getViewportWidth(), client.getViewportHeight());
	}
}

package com.fogofwar.render.world;
import com.fogofwar.render.BoundaryPathBuilder;
import com.fogofwar.render.RenderCenter;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import java.awt.Rectangle;
import java.awt.geom.GeneralPath;
final class WorldRenderBoundary implements BoundaryPathBuilder.Strategy {
	private final Client client;
	private int[] boundaryX;
	private int[] boundaryY;
	private boolean[] boundaryVisible;
	private PathCache seaRenderAreaBoundary;
	private PathCache landRenderAreaBoundary;
	private Rectangle currentViewport;
	private int currentCenterX, currentCenterY;
	WorldRenderBoundary(Client client) { this.client = client; }
	GeneralPath createSeaRenderAreaBoundary(RenderCenter rc, int radius, Rectangle viewport) {
		if (seaRenderAreaBoundary == null) seaRenderAreaBoundary = new PathCache();
		return buildRenderAreaBoundary(rc, radius, viewport, seaRenderAreaBoundary);
	}
	GeneralPath createLandRenderAreaBoundary(RenderCenter rc, int radius, Rectangle viewport) {
		if (landRenderAreaBoundary == null) landRenderAreaBoundary = new PathCache();
		return buildRenderAreaBoundary(rc, radius, viewport, landRenderAreaBoundary);
	}
	private GeneralPath buildRenderAreaBoundary(RenderCenter rc, int radius, Rectangle viewport, PathCache cache) {
		WorldView worldView = rc.getWorldView();
		LocalPoint centerLp = rc.snappedCenter();
		int plane = rc.getWorldPoint().getPlane();
		if (centerLp == null) return null;
		Point centerPoint = Perspective.localToCanvas(client, centerLp, plane);
		currentCenterX = centerPoint != null ? centerPoint.getX() : viewport.x + viewport.width / 2;
		currentCenterY = centerPoint != null ? centerPoint.getY() : viewport.y + viewport.height - 1;
		currentViewport = viewport;
		if (cache.matches(client, worldView, centerLp, radius, plane, viewport, currentCenterX, currentCenterY)) return cache.lastPath();
		LocalPoint[] samples = cache.samples(worldView, centerLp, radius);
		ensureBoundaryCapacity(samples.length);
		for (int i = 0; i < samples.length; i++) {
			Point point = Perspective.localToCanvas(client, samples[i], plane);
			boundaryVisible[i] = point != null;
			if (point != null) {
				boundaryX[i] = point.getX();
				boundaryY[i] = point.getY();
			}
		}
		double arcRadius = Math.max(viewport.width, viewport.height) * 2.0;
		BoundaryPathBuilder.build(cache.working(), boundaryX, boundaryY, boundaryVisible, samples.length, currentCenterX, currentCenterY, arcRadius, this);
		return cache.save(client, worldView, centerLp, radius, plane, viewport, currentCenterX, currentCenterY);
	}
	private void ensureBoundaryCapacity(int capacity) {
		if (boundaryX != null && boundaryX.length >= capacity) return;
		boundaryX = new int[capacity];
		boundaryY = new int[capacity];
		boundaryVisible = new boolean[capacity];
	}
	@Override
	public GeneralPath coverage(GeneralPath path) { return fallback(path); }
	@Override
	public boolean isValid(GeneralPath path) { return path != null && path.contains(currentCenterX, currentCenterY); }
	@Override
	public GeneralPath fallback(GeneralPath path) { return fullViewportCoveragePath(path); }
	private GeneralPath fullViewportCoveragePath(GeneralPath path) {
		Rectangle viewport = currentViewport;
		path.reset();
		path.moveTo(viewport.x - 1, viewport.y - 1);
		path.lineTo(viewport.x + viewport.width + 1, viewport.y - 1);
		path.lineTo(viewport.x + viewport.width + 1, viewport.y + viewport.height + 1);
		path.lineTo(viewport.x - 1, viewport.y + viewport.height + 1);
		path.closePath();
		return path;
	}
	private static final class PathCache {
		private GeneralPath working = new GeneralPath();
		private GeneralPath lastPath = new GeneralPath();
		private LocalPoint[] samples;
		private WorldView sampleWorldView;
		private WorldView worldView;
		private boolean valid, gpu;
		private int worldViewId, centerLocalX, centerLocalY, radius, plane, boundsX, boundsY, boundsW, boundsH, centerPointX, centerPointY;
		private int camX, camY, camZ, camPitch, camYaw, scale;
		private float camFpX, camFpY, camFpZ, camFpPitch, camFpYaw;
		private int sampleCenterX, sampleCenterY, sampleRadius;
		private GeneralPath working() { return working; }
		private GeneralPath lastPath() { return lastPath; }
		private LocalPoint[] samples(WorldView worldView, LocalPoint center, int radius) {
			if (sampleWorldView == worldView && sampleCenterX == center.getX() && sampleCenterY == center.getY() && sampleRadius == radius) return samples;
			int localRadius = radius * Perspective.LOCAL_TILE_SIZE + Perspective.LOCAL_HALF_TILE_SIZE;
			int sideSamples = radius * 2 + 1;
			int step = localRadius * 2 / sideSamples;
			int minX = center.getX() - localRadius;
			int maxX = center.getX() + localRadius;
			int minY = center.getY() - localRadius;
			int maxY = center.getY() + localRadius;
			samples = new LocalPoint[sideSamples * 4];
			int index = 0;
			for (int i = 0; i < sideSamples; i++) samples[index++] = new LocalPoint(minX + i * step, maxY, worldView);
			for (int i = 0; i < sideSamples; i++) samples[index++] = new LocalPoint(maxX, maxY - i * step, worldView);
			for (int i = 0; i < sideSamples; i++) samples[index++] = new LocalPoint(maxX - i * step, minY, worldView);
			for (int i = 0; i < sideSamples; i++) samples[index++] = new LocalPoint(minX, minY + i * step, worldView);
			sampleWorldView = worldView;
			sampleCenterX = center.getX();
			sampleCenterY = center.getY();
			sampleRadius = radius;
			return samples;
		}
		private boolean matches(Client client, WorldView worldView, LocalPoint centerLp, int radius, int plane, Rectangle bounds, int centerPointX, int centerPointY) {
			return valid
					&& this.worldView == worldView
					&& this.worldViewId == worldView.getId()
					&& centerLocalX == centerLp.getX()
					&& centerLocalY == centerLp.getY()
					&& this.radius == radius
					&& this.plane == plane
					&& boundsX == bounds.x
					&& boundsY == bounds.y
					&& boundsW == bounds.width
					&& boundsH == bounds.height
					&& this.centerPointX == centerPointX
					&& this.centerPointY == centerPointY
					&& gpu == client.isGpu()
					&& camX == client.getCameraX()
					&& camY == client.getCameraY()
					&& camZ == client.getCameraZ()
					&& camPitch == client.getCameraPitch()
					&& camYaw == client.getCameraYaw()
					&& scale == client.getScale()
					&& Float.compare(camFpX, client.getCameraFpX()) == 0
					&& Float.compare(camFpY, client.getCameraFpY()) == 0
					&& Float.compare(camFpZ, client.getCameraFpZ()) == 0
					&& Float.compare(camFpPitch, client.getCameraFpPitch()) == 0
					&& Float.compare(camFpYaw, client.getCameraFpYaw()) == 0;
		}
		private GeneralPath save(Client client, WorldView worldView, LocalPoint centerLp, int radius, int plane, Rectangle bounds, int centerPointX, int centerPointY) {
			GeneralPath path = working;
			working = lastPath;
			lastPath = path;
			working.reset();
			valid = true;
			this.worldView = worldView;
			this.worldViewId = worldView.getId();
			this.centerLocalX = centerLp.getX();
			this.centerLocalY = centerLp.getY();
			this.radius = radius;
			this.plane = plane;
			this.boundsX = bounds.x;
			this.boundsY = bounds.y;
			this.boundsW = bounds.width;
			this.boundsH = bounds.height;
			this.centerPointX = centerPointX;
			this.centerPointY = centerPointY;
			gpu = client.isGpu();
			camX = client.getCameraX();
			camY = client.getCameraY();
			camZ = client.getCameraZ();
			camPitch = client.getCameraPitch();
			camYaw = client.getCameraYaw();
			scale = client.getScale();
			camFpX = client.getCameraFpX();
			camFpY = client.getCameraFpY();
			camFpZ = client.getCameraFpZ();
			camFpPitch = client.getCameraFpPitch();
			camFpYaw = client.getCameraFpYaw();
			return lastPath;
		}
	}
}

package com.fogofwar.state;
import com.fogofwar.config.FogOfWarConfig;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.gameval.VarbitID;
import javax.inject.Inject;
import javax.inject.Singleton;
@Singleton
public class ClientState {
	private final Client client;
	private final FogOfWarConfig config;
	@Inject
	public ClientState(Client client, FogOfWarConfig config) {
		this.client = client;
		this.config = config;
	}
	public boolean isLoggedIn() { return client.getGameState() == GameState.LOGGED_IN; }
	public boolean isCutsceneSuppressed() { return config.disableDuringCutscenes() && client.getVarbitValue(VarbitID.CUTSCENE_STATUS) == 1; }
	public boolean isNotInWilderness() { return client.getVarbitValue(VarbitID.INSIDE_WILDERNESS) != 1; }
	public boolean isSailing() { return client.getVarbitValue(VarbitID.SAILING_BOARDED_BOAT) == 1; }
	public Player getLocalPlayerIfReady() { return isLoggedIn() && !isCutsceneSuppressed() ? client.getLocalPlayer() : null; }
}

