package com.fogofwar.fade;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
public class FadingPlayerPredictorTest {
	@Test
	public void velocityUsesLastTwoLocations() {
		assertEquals(new WorldPoint(2, -1, 0), FadingPlayerPredictor.getVelocity(new WorldPoint(12, 19, 0), new WorldPoint(10, 20, 0)));
		WorldPoint zero = FadingPlayerPredictor.getVelocity(new WorldPoint(12, 19, 0), null);
		assertEquals(new WorldPoint(0, 0, 0), zero);
		assertSame(zero, FadingPlayerPredictor.getVelocity(new WorldPoint(20, 30, 0), null));
	}
	@Test
	public void nearRenderLimitHonorsEdgeAndRunning() {
		WorldPoint local = new WorldPoint(100, 100, 0);
		assertTrue(FadingPlayerPredictor.isNearRenderLimit(new WorldPoint(114, 100, 0), local, new WorldPoint(0, 0, 0), 15));
		assertFalse(FadingPlayerPredictor.isNearRenderLimit(new WorldPoint(112, 100, 0), local, new WorldPoint(1, 0, 0), 15));
		assertTrue(FadingPlayerPredictor.isNearRenderLimit(new WorldPoint(113, 100, 0), local, new WorldPoint(2, 0, 0), 15));
	}
	@Test
	public void initialLocationMatchesExtrapolationRules() {
		WorldPoint local = new WorldPoint(100, 100, 0);
		assertEquals(new WorldPoint(116, 100, 0), FadingPlayerPredictor.getInitialFadeLocation(new WorldPoint(114, 100, 0), local, new WorldPoint(1, 0, 0), true, 15, true));
		assertEquals(new WorldPoint(114, 100, 0), FadingPlayerPredictor.getInitialFadeLocation(new WorldPoint(114, 100, 0), local, new WorldPoint(-1, 0, 0), true, 15, true));
		assertEquals(new WorldPoint(114, 100, 0), FadingPlayerPredictor.getInitialFadeLocation(new WorldPoint(114, 100, 0), local, new WorldPoint(1, 0, 0), false, 15, true));
	}
}

package com.fogofwar.fade;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import java.awt.Color;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertSame;
public class FadingPlayerTest {
	@Test
	public void cachesColoursUntilVisibleInputsChange() {
		FadingPlayer player = new FadingPlayer(null, null, new WorldPoint(0, 0, 0), 15);
		Color base = new Color(100, 50, 25, 160);
		Color initial = player.getColor(base, 4);
		assertSame(initial, player.getColor(base, 4));
		assertSame(player.getDarkerColor(base, 4), player.getDarkerColor(base, 4));
		player.setTicksSinceDisappeared(1);
		Color faded = player.getColor(base, 4);
		assertNotSame(initial, faded);
		assertEquals(120, faded.getAlpha());
	}
}

package com.fogofwar.render;
import org.junit.Test;
import java.awt.Rectangle;
import java.awt.geom.GeneralPath;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
public class BoundaryPathBuilderTest {
	@Test
	public void buildsCompletePrimitiveBoundary() {
		GeneralPath path = new GeneralPath();
		GeneralPath result = BoundaryPathBuilder.build(path, new int[]{0, 10, 10, 0}, new int[]{0, 0, 10, 10}, new boolean[]{true, true, true, true}, 4, 5, 5, 20, new ValidStrategy());
		assertSame(path, result);
		assertEquals(new Rectangle(0, 0, 10, 10), path.getBounds());
		assertTrue(path.contains(5, 5));
	}
	@Test
	public void retriesThenFallsBackWhenBoundaryIsInvalid() {
		GeneralPath fallback = new GeneralPath();
		BoundaryPathBuilder.Strategy strategy = new BoundaryPathBuilder.Strategy() {
			@Override
			public GeneralPath coverage(GeneralPath path) { return path; }
			@Override
			public boolean isValid(GeneralPath path) { return false; }
			@Override
			public GeneralPath fallback(GeneralPath path) { return fallback; }
		};
		assertSame(fallback, BoundaryPathBuilder.build(new GeneralPath(), new int[]{0, 10, 10}, new int[]{0, 0, 10}, new boolean[]{true, false, true}, 3, 5, 5, 20, strategy));
	}
	private static final class ValidStrategy implements BoundaryPathBuilder.Strategy {
		@Override
		public GeneralPath coverage(GeneralPath path) { return path; }
		@Override
		public boolean isValid(GeneralPath path) { return true; }
		@Override
		public GeneralPath fallback(GeneralPath path) { return path; }
	}
}

package com.fogofwar.render;
import org.junit.Test;
import java.awt.Color;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
public class FogRenderTest {
	@Test
	public void sailingSeaColourRetainsVisibleAlphaFloorAndCachesResult() {
